-- GERADO por scripts/instrumentos/gerar-catalogos.mjs a partir dos catálogos do portal. Não editar à mão.
-- Leva ao banco os catálogos do Recredenciamento 2017 e do Novo Instrumento 2026 (curso e institucional)
-- e a equivalência Reconhecimento 2017 → Novo Instrumento 2026 de curso (33 indicadores, 51 pares).
-- Aditiva: duas colunas jsonb novas, uma tabela nova e carga para a UNITOP (mesmo escopo do catálogo do
-- Reconhecimento já aplicado em 20261117153003). Sem alteração de permissões existentes.
-- Os catálogos novos entram com is_active=false: a pré-validação lê só catálogos ativos, então o
-- comportamento dela e a revisão de cache (vertice_doc_rules_revision) não mudam. Ligá-los à
-- pré-validação é decisão própria (passo 4 do plano dos instrumentos).

ALTER TABLE public.vertice_instrument_catalog ADD COLUMN IF NOT EXISTS structure jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE public.vertice_instrument_objects ADD COLUMN IF NOT EXISTS reference jsonb NOT NULL DEFAULT '{}'::jsonb;
COMMENT ON COLUMN public.vertice_instrument_catalog.structure IS 'Dimensões ou eixos do instrumento (código, nome, peso) e forma de cálculo do conceito, quando houver.';
COMMENT ON COLUMN public.vertice_instrument_objects.reference IS 'Dados estruturados do indicador: descritores de conceito 1 a 5, aplicabilidade, evidências esperadas, variantes por perfil e marcação de provisório.';
ALTER TABLE public.vertice_instrument_catalog ADD CONSTRAINT vertice_instrument_catalog_id_institution_key UNIQUE (id, institution_id);

-- Equivalência entre indicadores de dois catálogos da mesma instituição. Não é texto oficial:
-- a proveniência registra a origem e o grau é a leitura do Vértice (direto, parcial, complementar).
CREATE TABLE public.vertice_instrument_equivalences (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 institution_id uuid NOT NULL,
 source_catalog_id uuid NOT NULL,
 source_code text NOT NULL,
 target_catalog_id uuid NOT NULL,
 target_code text NOT NULL,
 degree text NOT NULL CHECK (degree IN ('direto','parcial','complementar')),
 note text,
 provenance jsonb NOT NULL DEFAULT '{}'::jsonb,
 created_at timestamptz NOT NULL DEFAULT now(),
 CHECK (source_catalog_id <> target_catalog_id),
 UNIQUE (source_catalog_id, source_code, target_catalog_id, target_code),
 FOREIGN KEY (source_catalog_id, institution_id) REFERENCES public.vertice_instrument_catalog(id, institution_id) ON DELETE CASCADE,
 FOREIGN KEY (target_catalog_id, institution_id) REFERENCES public.vertice_instrument_catalog(id, institution_id) ON DELETE CASCADE,
 FOREIGN KEY (source_catalog_id, source_code) REFERENCES public.vertice_instrument_objects(catalog_id, object_code) ON DELETE CASCADE,
 FOREIGN KEY (target_catalog_id, target_code) REFERENCES public.vertice_instrument_objects(catalog_id, object_code) ON DELETE CASCADE
);
CREATE INDEX vertice_instrument_equivalences_target_idx ON public.vertice_instrument_equivalences(target_catalog_id, target_code);
CREATE INDEX vertice_instrument_equivalences_inst_idx ON public.vertice_instrument_equivalences(institution_id);
ALTER TABLE public.vertice_instrument_equivalences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.vertice_instrument_equivalences FROM anon, authenticated;
GRANT SELECT ON public.vertice_instrument_equivalences TO authenticated;
CREATE POLICY vertice_instrument_equivalences_read ON public.vertice_instrument_equivalences
 FOR SELECT TO authenticated USING (vertice_private.can_read_institution(institution_id));

DO $seed$
DECLARE target uuid; cat uuid; src uuid; dst uuid;
BEGIN
 SELECT id INTO STRICT target FROM public.vertice_institutions WHERE emec_code='4969' AND acronym='UNITOP';

 INSERT INTO public.vertice_instrument_catalog(institution_id,instrument_code,instrument_label,instrument_version,is_active,scope,source_provenance,structure)
 VALUES(target,'recredenciamento_institucional','Instrumento de Avaliação Institucional Externa — 2017','2017',false,'instituicao','{"origin":"portal","source_file":"source-overrides/client/src/lib/avaliacao-institucional.json","sha256_source_file":"4d87ce4faa083baeaea42fa46fd6c12b971f6a9a37601fa85f3b282a0f7a65c4","official_text_verified":false,"publisher":"INEP/DAES — Diretoria de Avaliação da Educação Superior","edition":"2017","note":"Transcrição mantida no portal. Conferência contra o PDF oficial do INEP pendente; não substitui o texto oficial."}'::jsonb,'{"dimension_kind":"eixo","dimensions":[{"code":1,"name":"Planejamento e Avaliação Institucional","weight":10},{"code":2,"name":"Desenvolvimento Institucional","weight":30},{"code":3,"name":"Políticas Acadêmicas","weight":10},{"code":4,"name":"Políticas de Gestão","weight":20},{"code":5,"name":"Infraestrutura","weight":30}],"concept":"media_ponderada_dos_eixos","scale":[1,5]}'::jsonb)
 ON CONFLICT(institution_id,instrument_code,instrument_version) DO NOTHING;
 SELECT id INTO STRICT cat FROM public.vertice_instrument_catalog WHERE institution_id=target AND instrument_code='recredenciamento_institucional' AND instrument_version='2017' AND source_provenance->>'sha256_source_file'='4d87ce4faa083baeaea42fa46fd6c12b971f6a9a37601fa85f3b282a0f7a65c4';
 INSERT INTO public.vertice_instrument_objects(catalog_id,object_code,dimension,object_label,description,reference)
 SELECT cat,v.code,v.dim,v.label,v.descr,v.ref FROM (VALUES
  ('1.1','1','Evolução institucional a partir dos processos de Planejamento e Avaliação Institucional',NULL,'{"sinaes_dimension":8,"concept_descriptors":{"1":"O Relato Institucional não contempla o histórico da IES, os conceitos de avaliações externas, o desenvolvimento e divulgação dos processos de autoavaliação, o plano de melhorias ou os processos de gestão a partir das avaliações externas e internas.","2":"O Relato Institucional contempla o histórico da IES, os conceitos de avaliações externas, o desenvolvimento e divulgação dos processos de autoavaliação, o plano de melhorias e os processos de gestão a partir das avaliações externas e internas, mas não evidencia a evolução institucional.","3":"O Relato Institucional demonstra a análise do histórico da IES, do conceito de avaliações externas, do desenvolvimento e divulgação dos processos de autoavaliação, do plano de melhorias e dos processos de gestão a partir das avaliações externas e internas e evidencia a evolução institucional.","4":"O Relato Institucional demonstra a análise do histórico da IES, do conceito de avaliações externas, do desenvolvimento e divulgação dos processos de autoavaliação, do plano de melhorias e dos processos de gestão a partir das avaliações externas e internas, demonstra a implementação de ações efetivas na gestão da IES e evidencia a evolução institucional.","5":"O Relato Institucional analisa e sintetiza o histórico da IES, o conceito de avaliações externas, o desenvolvimento e divulgação dos processos de autoavaliação, o plano de melhorias e processos de gestão a partir das avaliações externas e internas, demonstra a implementação de ações efetivas na gestão da IES, evidencia a evolução institucional e é apropriado pelos gestores, docentes/colaboradores e discentes."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Relato Institucional do triênio, aprovado pelo dirigente máximo, com data e assinatura","PDI vigente e o PDI anterior, para demonstrar a evolução do planejamento","Relatórios de avaliação externa do período: credenciamento anterior e avaliações de curso","Plano de melhorias decorrente das avaliações interna e externa, com responsável e prazo","Ata do colegiado superior que aprova o Relato Institucional"],"complementar":["Relatório de gestão anual com as decisões tomadas no período","Organograma com a indicação dos responsáveis por cada área","Painel de indicadores institucionais acompanhado pela gestão","Registro das devolutivas de avaliação às unidades acadêmicas"],"resultado":["Série comparativa de indicadores do triênio, com valor de partida, valor atual e variação","Registro de ação implementada a partir de avaliação externa, com data de início e efeito medido"]},"alerta":"Relato Institucional que apenas descreve o histórico, sem mostrar a decisão tomada e o efeito medido, sustenta no máximo o conceito 3. Relato desatualizado ou que a gestão não reconhece como seu derruba o indicador inteiro."}'::jsonb),
  ('1.2','1','Processo de autoavaliação institucional',NULL,'{"sinaes_dimension":8,"concept_descriptors":{"1":"Não há processo de autoavaliação institucional.","2":"Há processo de autoavaliação institucional, mas não atende às necessidades institucionais, como instrumento de gestão e de ação acadêmico-administrativa de melhoria institucional.","3":"Há processo de autoavaliação institucional e atende às necessidades institucionais, como instrumento de gestão e de ação acadêmico-administrativa de melhoria institucional.","4":"Há processo de autoavaliação institucional e atende às necessidades institucionais, como instrumento de gestão e de ação acadêmico-administrativa de melhoria institucional, com evidência de que todos os segmentos da comunidade acadêmica estão sensibilizados para a sua relevância.","5":"Há processo de autoavaliação institucional e atende às necessidades institucionais, como instrumento de gestão e de ação acadêmico-administrativa de melhoria institucional, com evidência de que todos os segmentos da comunidade acadêmica estão sensibilizados e se apropriam seus resultados."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Norma de criação e funcionamento da CPA, com composição e atribuições","Plano de trabalho da CPA para o triênio, aprovado pelo colegiado","Instrumentos de coleta aplicados no período, com registro de aplicação e período de campo","Metodologia de autoavaliação documentada, com dimensões, indicadores e escala","Designação dos membros da CPA por portaria, com vigência do mandato"],"complementar":["Atas de reunião da CPA do triênio","Cronograma de execução da autoavaliação","Material de sensibilização usado junto aos segmentos","Relatórios setoriais produzidos a partir dos dados da CPA"],"resultado":["Sequência documentada de achado, plano de ação, execução e verificação","Registro de que os resultados chegaram a cada segmento, com data e forma de devolutiva"]},"alerta":"CPA que existe apenas na portaria, sem ata, sem coleta e sem devolutiva, não passa do conceito 3. O corte mais comum é ter o processo e não conseguir provar que os resultados voltaram para a comunidade."}'::jsonb),
  ('1.3','1','Autoavaliação institucional: participação da comunidade acadêmica',NULL,'{"sinaes_dimension":8,"concept_descriptors":{"1":"Não há processo de autoavaliação institucional.","2":"O processo de autoavaliação não ocorre com participação da sociedade civil organizada e de todos os segmentos da comunidade acadêmica.","3":"O processo de autoavaliação ocorre com participação da sociedade civil organizada e de todos os segmentos da comunidade acadêmica (vedada a composição que privilegie a maioria absoluta de um deles).","4":"O processo de autoavaliação ocorre com participação da sociedade civil organizada, de todos os segmentos da comunidade acadêmica (vedada a composição que privilegie a maioria absoluta de um deles) e com abrangência de instrumentos de coleta.","5":"O processo de autoavaliação ocorre com participação da sociedade civil organizada e de todos os segmentos da comunidade acadêmica (vedada a composição que privilegie a maioria absoluta de um deles), com abrangência de instrumentos de coleta e índice de participação crescente."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Composição da CPA com representantes de todos os segmentos e da sociedade civil organizada","Comprovação de que nenhum segmento detém maioria absoluta na composição","Registro de participação por segmento: listas de presença, adesão por formulário, quórum de assembleia"],"complementar":["Campanhas de mobilização e chamadas públicas de participação","Atas com registro de quórum por segmento","Relatório de análise de adesão por segmento"],"resultado":["Série de taxa de participação nos três anos, com tendência de crescimento","Ação corretiva adotada quando um segmento ficou abaixo da meta, com efeito no ano seguinte"]},"alerta":"Composição que privilegia a maioria absoluta de um segmento reprova o critério, não apenas limita o conceito. Índice de participação estagnado ou em queda impede o conceito 5 mesmo com instrumentos sofisticados."}'::jsonb),
  ('1.4','1','Autoavaliação institucional e avaliações externas: análise e divulgação dos resultados',NULL,'{"sinaes_dimension":8,"concept_descriptors":{"1":"Não há divulgação dos resultados da autoavaliação institucional ou de avaliações externas.","2":"Os resultados divulgados, referentes à autoavaliação institucional e às avaliações externas, não estão disponíveis para todos os segmentos da comunidade acadêmica.","3":"Os resultados divulgados, referentes à autoavaliação institucional e às avaliações externas, são descritivos e estão disponíveis para todos os segmentos da comunidade acadêmica.","4":"Os resultados divulgados, referentes à autoavaliação institucional e às avaliações externas, são analíticos e estão disponíveis para todos os segmentos da comunidade acadêmica.","5":"Os resultados divulgados, referentes à autoavaliação institucional e às avaliações externas, são analíticos e apropriados por todos os segmentos da comunidade acadêmica."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Documento analítico dos resultados da autoavaliação, com interpretação e não apenas tabelas","Documento analítico dos resultados das avaliações externas do período","Prova de divulgação a todos os segmentos: publicação, portal, mural, reunião com lista de presença"],"complementar":["Apresentações de devolutiva por unidade","Notícias e comunicados institucionais sobre os resultados","Relatório de oficinas de leitura dos dados com a comunidade"],"resultado":["Plano de melhoria derivado da análise, com responsável, prazo e verificação de execução","Registro de decisão de gestão alterada por causa de um resultado divulgado"]},"alerta":"Divulgar o número sem análise não atende ao critério, que exige resultado analítico e apropriado. Divulgação restrita ao site, sem alcance comprovado aos segmentos, segura o conceito em 4."}'::jsonb),
  ('1.5','1','Relatórios de autoavaliação',NULL,'{"sinaes_dimension":8,"concept_descriptors":{"1":"Não há relatórios de autoavaliação postados.","2":"Os relatórios de autoavaliação não estão de acordo com a previsão de postagem para cada ano do triênio (considerando os relatórios parciais e final previstos no planejamento da CPA).","3":"Os relatórios de autoavaliação estão de acordo com a previsão de postagem para cada ano do triênio (considerando os relatórios parciais e final previstos no planejamento da CPA).","4":"Os relatórios de autoavaliação estão de acordo com a previsão de postagem para cada ano do triênio (considerando os relatórios parciais e final previstos no planejamento da CPA), possuem clara relação entre si e impactam o processo de gestão da instituição.","5":"Os relatórios de autoavaliação estão de acordo com a previsão de postagem para cada ano do triênio (considerando os relatórios parciais e final previstos no planejamento da CPA), possuem clara relação entre si, impactam o processo de gestão da instituição e promovem mudanças inovadoras."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Relatórios de autoavaliação parciais e final do triênio, conforme o planejamento da CPA","Comprovante de postagem ou protocolo de cada relatório na data prevista","Documento que mostra a relação entre os relatórios: o que avançou de um para o outro"],"complementar":["Versões aprovadas pela CPA antes da postagem","Registro de envio ao sistema do MEC e ao Inep, quando houver"],"resultado":["Evidência de que o relatório alterou o orçamento, o PDI ou o plano de ação","Mudança inovadora implantada e documentada a partir de achado do relatório"]},"alerta":"Relatório produzido só para cumprir prazo, sem continuidade em relação ao anterior, não alcança o conceito 5. Atraso na postagem de um dos anos do triênio já compromete o critério."}'::jsonb),
  ('2.1','2','Missão, objetivos, metas e valores institucionais',NULL,'{"sinaes_dimension":1,"concept_descriptors":{"1":"A missão, os objetivos e as metas da instituição não estão consonantes com o PDI.","2":"A missão, os objetivos e as metas da instituição estão expressos no PDI, mas não se comunicam com as políticas de ensino, de extensão e de pesquisa (esta última, considerando a organização acadêmica).","3":"A missão, os objetivos e as metas da instituição estão expressos no PDI e se comunicam com as políticas de ensino, de extensão e de pesquisa (esta última, considerando a organização acadêmica).","4":"A missão, os objetivos, as metas e os valores da instituição estão expressos no PDI, comunicam-se com as políticas de ensino, de extensão e de pesquisa (esta última, considerando a organização acadêmica) e se traduzem em ações institucionais internas, transversais a todos os cursos.","5":"A missão, os objetivos, as metas e os valores da instituição estão expressos no PDI, comunicam-se com as políticas de ensino, de extensão e de pesquisa (esta última, considerando a organização acadêmica), traduzem-se em ações institucionais internas, transversais a todos os cursos, e externas, por meio dos projetos de responsabilidade social."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["PDI vigente com missão, objetivos, metas e valores explicitados","Desdobramento da missão em planos por área, com metas e prazos","Ata do colegiado superior que aprova o PDI","Peças de comunicação institucional que levam a missão à comunidade"],"complementar":["Projetos de responsabilidade social em execução, com público e resultados","Plano de metas por curso, transversal a todos os cursos ofertados","Registro de revisão periódica da missão e dos valores"],"resultado":["Painel de cumprimento das metas do PDI no triênio, com meta, realizado e desvio","Evidência de ação externa concreta derivada dos valores declarados"]},"alerta":"Missão genérica, que não se traduz em ação verificável e transversal aos cursos, fica em conceito 3. Valores que aparecem só no site, sem projeto correspondente, não contam."}'::jsonb),
  ('2.2','2','PDI, planejamento didático-instrucional e política de ensino de graduação e de pós-graduação',NULL,'{"sinaes_dimension":1,"concept_descriptors":{"1":"Não há alinhamento entre o PDI e a política de ensino.","2":"Há alinhamento entre o PDI e a política de ensino, mas não se consideram os métodos e as técnicas didático-pedagógicas, metodologias que favorecem o atendimento educacional especializado ou as atividades de avaliação.","3":"Há alinhamento entre o PDI e a política de ensino, considerando os métodos e as técnicas didático-pedagógicas, metodologias que favorecem o atendimento educacional especializado e as atividades de avaliação, o que se traduz nas práticas de ensino de graduação e de pós-graduação.","4":"Há alinhamento entre o PDI e a política de ensino, considerando os métodos e as técnicas didático-pedagógicas, metodologias que favorecem o atendimento educacional especializado e as atividades de avaliação, o que se traduz nas práticas de ensino de graduação e de pós-graduação, com incorporação de avanços tecnológicos e com metodologia que incentiva a interdisciplinaridade.","5":"Há alinhamento entre o PDI e a política de ensino, considerando os métodos e as técnicas didático-pedagógicas, metodologias que favorecem o atendimento educacional especializado e as atividades de avaliação, o que se traduz nas práticas de ensino de graduação e de pós-graduação, com incorporação de avanços tecnológicos e com metodologia que incentiva a interdisciplinaridade, e a promoção de ações reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":"Para faculdades e centros universitários, considerar a pós-graduação apenas quando houver previsão no PDI.","evidence":{"obrigatoria":["PDI com o capítulo da política de ensino de graduação e de pós-graduação","PPC vigente dos cursos com métodos e técnicas didático-pedagógicas descritos","Política de avaliação da aprendizagem, com instrumentos e critérios","Norma institucional de atendimento educacional especializado e acessibilidade metodológica"],"complementar":["Registro de práticas interdisciplinares implantadas","Relatório de incorporação de avanços tecnológicos ao ensino"],"resultado":["Evidência de que a prática de ensino mudou após o PDI, com antes e depois","Ação exitosa ou inovadora de ensino documentada e replicada em mais de um curso"]},"alerta":"PDI bonito e prática de sala de aula desconectada derruba o indicador: o critério é o alinhamento, não o texto. Metodologia de acessibilidade declarada sem aplicação em PPC não conta."}'::jsonb),
  ('2.3','2','PDI, política e práticas de pesquisa ou iniciação científica, de inovação tecnológica e de desenvolvimento artístico e cultural',NULL,'{"sinaes_dimension":1,"concept_descriptors":{"1":"Não há alinhamento entre o PDI e a política e as práticas de pesquisa ou iniciação científica, de inovação tecnológica e de desenvolvimento artístico e cultural.","2":"Há alinhamento entre o PDI e a política e as práticas de pesquisa ou iniciação científica, de inovação tecnológica e de desenvolvimento artístico e cultural, mas não se verificam práticas acadêmicas voltadas à produção e à interpretação do conhecimento.","3":"Há alinhamento entre o PDI e a política e as práticas de pesquisa ou iniciação científica, de inovação tecnológica e de desenvolvimento artístico e cultural, verificando-se práticas acadêmicas voltadas à produção e à interpretação do conhecimento.","4":"Há alinhamento entre o PDI e a política e as práticas de pesquisa ou iniciação científica, de inovação tecnológica e de desenvolvimento artístico e cultural, verificando-se práticas acadêmicas voltadas à produção e à interpretação do conhecimento, havendo linhas de pesquisa e de trabalho transversais aos cursos ofertados.","5":"Há alinhamento entre o PDI e a política e as práticas de pesquisa ou iniciação científica, de inovação tecnológica e de desenvolvimento artístico e cultural, verificando-se práticas acadêmicas voltadas à produção e à interpretação do conhecimento, havendo linhas de pesquisa e de trabalho transversais aos cursos ofertados e mecanismos de transmissão dos resultados para a comunidade."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de pesquisa ou iniciação científica, inovação e desenvolvimento artístico e cultural","Linhas de pesquisa e de trabalho transversais aos cursos ofertados","Registro dos grupos e projetos em execução, com participantes e vigência","Mecanismo de transmissão dos resultados para a comunidade: evento, publicação, mostr"],"complementar":["Convênios e parcerias com agências de fomento ou instituições","Relatório de produção do período"],"resultado":["Série de projetos, bolsas e publicações nos três anos","Evidência de resultado transmitido à comunidade externa, com data e público"]},"alerta":"Pesquisa concentrada em um curso só, sem linha transversal, não atende ao critério. Projeto sem mecanismo de transmissão dos resultados fica em conceito 3."}'::jsonb),
  ('2.4','2','PDI, políticas institucionais voltadas à valorização da diversidade, do meio ambiente, da memória cultural, da produção artística e do patrimônio cultural, e ações afirmativas de defesa e promoção dos direitos humanos',NULL,'{"sinaes_dimension":3,"concept_descriptors":{"1":"O PDI não possui políticas institucionais e não aborda problemática relacionada a ações voltadas à valorização da diversidade, do meio ambiente, da memória cultural, da produção artística e do patrimônio cultural, ou a ações afirmativas de defesa e promoção dos direitos humanos e da igualdade étnico-racial.","2":"O PDI não possui políticas institucionais, mas aborda problemática relacionada a ações voltadas à valorização da diversidade, do meio ambiente, da memória cultural, da produção artística e do patrimônio cultural, e a ações afirmativas de defesa e promoção dos direitos humanos e da igualdade étnico-racial.","3":"O PDI possui políticas institucionais que se traduzem em ações voltadas à valorização da diversidade, do meio ambiente, da memória cultural, da produção artística e do patrimônio cultural, e em ações afirmativas de defesa e promoção dos direitos humanos e da igualdade étnico-racial.","4":"O PDI possui políticas institucionais que se traduzem em ações voltadas à valorização da diversidade, do meio ambiente, da memória cultural, da produção artística e do patrimônio cultural, e em ações afirmativas de defesa e promoção dos direitos humanos e da igualdade étnico-racial, de modo transversal aos cursos ofertados, ampliando as competências dos egressos.","5":"O PDI possui políticas institucionais que se traduzem em ações voltadas à valorização da diversidade, do meio ambiente, da memória cultural, da produção artística e do patrimônio cultural, e em ações afirmativas de defesa e promoção dos direitos humanos e da igualdade étnico-racial, de modo transversal aos cursos ofertados, ampliando as competências dos egressos e ofertando mecanismos de transmissão dos resultados para a comunidade."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política institucional de valorização da diversidade, do meio ambiente, da memória e do patrimônio cultural","Ações afirmativas de defesa dos direitos humanos e de igualdade étnico-racial, com norma e responsável","Registro das ações transversais aos cursos ofertados","Mecanismo de transmissão dos resultados para a comunidade"],"complementar":["Parcerias com movimentos sociais, museus e órgãos de preservação","Relatório de atividades culturais e ambientais do triênio"],"resultado":["Indicador de alcance das ações por curso, com meta e realizado","Evidência de ampliação de competência dos egressos atribuível à ação"]},"alerta":"Evento isolado no calendário não é política institucional. Sem transversalidade aos cursos e sem transmissão de resultados, o indicador não passa do conceito 3."}'::jsonb),
  ('2.5','2','PDI e políticas institucionais voltadas ao desenvolvimento econômico e à responsabilidade social',NULL,'{"sinaes_dimension":3,"concept_descriptors":{"1":"Não há alinhamento entre o PDI e as políticas institucionais voltadas ao desenvolvimento econômico e social.","2":"Há alinhamento entre o PDI e as políticas institucionais voltadas ao desenvolvimento econômico e social, mas não se consideram a melhoria das condições de vida da população e as ações de inclusão.","3":"Há alinhamento entre o PDI e as políticas institucionais para o desenvolvimento econômico e social, considerando a melhoria das condições de vida da população e as ações de inclusão.","4":"Há alinhamento entre o PDI e as políticas institucionais para o desenvolvimento econômico e social, considerando a melhoria das condições de vida da população e as ações de inclusão e empreendedorismo, articulando os objetivos e valores da IES.","5":"Há alinhamento entre o PDI e as políticas institucionais para o desenvolvimento econômico e social, considerando a melhoria das condições de vida da população e as ações de inclusão e empreendedorismo, articulando os objetivos e valores da IES, e a promoção de ações reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":"Para a modalidade EaD, considerar as especificidades da sede e dos polos.","evidence":{"obrigatoria":["Política institucional para o desenvolvimento econômico e social","Projetos de inclusão e de empreendedorismo em execução, com público e território","Ata ou resolução que vincula a política aos objetivos e valores da IES"],"complementar":["Convênios com poder público e setor produtivo local","Relatório de impacto das ações na comunidade"],"resultado":["Série de beneficiários e de projetos no triênio","Evidência de melhoria de condição de vida documentada, ainda que por amostra"]},"alerta":"Ação social pontual, sem política escrita e sem série, sustenta apenas o conceito 3. Projeto sem medição de efeito não fecha o 5."}'::jsonb),
  ('2.6','2','PDI e política institucional para a modalidade EaD','Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n° 1.134 de 10/10/2016.','{"sinaes_dimension":1,"concept_descriptors":{"1":"A política institucional para a modalidade a distância não está articulada com o PDI.","2":"A política institucional para a modalidade a distância está articulada com o PDI, mas não contempla o alinhamento da base tecnológica institucional com o projeto pedagógico da sua utilização.","3":"A política institucional para a modalidade a distância está articulada com o PDI e contempla o alinhamento da base tecnológica institucional com o projeto pedagógico da sua utilização.","4":"A política institucional para a modalidade a distância está articulada com o PDI e contempla o alinhamento da base tecnológica institucional com o projeto pedagógico da sua utilização, observando a formação pretendida para os discentes (na sede e nos polos).","5":"A política institucional para a modalidade a distância está articulada com o PDI e contempla o alinhamento da base tecnológica institucional com o projeto pedagógico da sua utilização, observando a formação pretendida para os discentes (na sede e nos polos) e considerando as condições reais da localidade de oferta."},"applicability":"Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n° 1.134 de 10/10/2016.","nota":null,"evidence":{"obrigatoria":["PDI com a política institucional para a modalidade a distância","Documento que alinha a base tecnológica institucional ao projeto pedagógico da modalidade","Projeto de formação pretendida para os discentes na sede e nos polos","Estudo das condições reais da localidade de oferta"],"complementar":["Plano de capacitação de tutores e de professores para EaD","Relatório de infraestrutura tecnológica disponível para a modalidade"],"resultado":["Indicador de execução da política EaD no triênio, com meta e realizado","Evidência de ajuste feito a partir das condições da localidade"]},"alerta":"Curso a distância funcionando sem política articulada ao PDI reprova o indicador, e o problema se repete em 2.7 e 5.13. Base tecnológica descrita sem vínculo com o projeto pedagógico não conta."}'::jsonb),
  ('2.7','2','Estudo para implantação de polos EaD','Exclusivo para modalidade a distância com previsão de polos.','{"sinaes_dimension":1,"concept_descriptors":{"1":"O PDI não apresenta estudo para implantação de polos EAD.","2":"O PDI apresenta estudo para implantação de polos EAD, mas não considera sua distribuição geográfica ou aspectos regionais sobre a população do ensino médio, a demanda por cursos superiores e a relação entre número de matriculados e de evadidos.","3":"O PDI apresenta estudo para implantação de polos EAD que considera sua distribuição geográfica e aspectos regionais sobre a população do ensino médio, a demanda por cursos superiores e a relação entre número de matriculados e de evadidos.","4":"O PDI apresenta estudo para implantação de polos EAD que considera sua distribuição geográfica e aspectos regionais sobre a população do ensino médio, a demanda por cursos superiores e a relação entre número de matriculados e de evadidos, bem como a contribuição do(s) curso(s) ofertado(s) para o desenvolvimento da comunidade.","5":"O PDI apresenta estudo para implantação de polos EAD que considera sua distribuição geográfica e aspectos regionais sobre a população do ensino médio, a demanda por cursos superiores e a relação entre número de matriculados e de evadidos, bem como a contribuição do(s) curso(s) ofertado(s) para o desenvolvimento da comunidade e os indicadores estabelecidos no PNE vigente."},"applicability":"Exclusivo para modalidade a distância com previsão de polos.","nota":null,"evidence":{"obrigatoria":["Estudo de implantação de polos EaD inserido no PDI","Análise de distribuição geográfica dos polos pretendidos","Dados regionais sobre população do ensino médio e demanda por curso superior","Relação entre matriculados e evadidos nos polos existentes","Demonstração da contribuição dos cursos para o desenvolvimento da comunidade"],"complementar":["Comparação com os indicadores do PNE vigente","Parecer da comissão própria de avaliação sobre a implantação"],"resultado":["Série de matrícula e evasão por polo, com análise de causa","Decisão de expansão ou de correção tomada com base no estudo"]},"alerta":"Estudo genérico, sem dado regional e sem série de evasão, não sustenta o conceito 5. Polo aberto antes do estudo inverte a lógica do critério."}'::jsonb),
  ('3.1','3','Políticas de ensino e ações acadêmico-administrativas para os cursos de graduação',NULL,'{"sinaes_dimension":2,"concept_descriptors":{"1":"As ações acadêmico-administrativas não estão relacionadas com a política de ensino para os cursos de graduação.","2":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de graduação, mas não consideram a atualização curricular sistemática, a oferta de componentes curriculares na modalidade a distância (quando previsto no PDI), a existência de programas de monitoria em uma ou mais áreas ou de nivelamento, transversais a todos os cursos.","3":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de graduação e consideram a atualização curricular sistemática, a oferta de componentes curriculares na modalidade a distância (quando previsto no PDI), a existência de programas de monitoria em uma ou mais áreas e de nivelamento, transversais a todos os cursos.","4":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de graduação e consideram a atualização curricular sistemática, a oferta de componentes curriculares na modalidade a distância (quando previsto no PDI), a existência de programas de monitoria em uma ou mais áreas, de nivelamento, transversais a todos os cursos, e de mobilidade acadêmica com instituições nacionais ou internacionais.","5":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de graduação e consideram a atualização curricular sistemática, a oferta de componentes curriculares na modalidade a distância (quando previsto no PDI), a existência de programas de monitoria em uma ou mais áreas, de nivelamento, transversais a todos os cursos, de mobilidade acadêmica com instituições nacionais ou internacionais, e a promoção de ações reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de ensino para a graduação, aprovada pelo colegiado competente","PPC vigente dos cursos, com registro de atualização curricular sistemática","Norma e registro de execução dos programas de monitoria, de nivelamento e de mobilidade acadêmica","Comprovação da oferta de componentes curriculares a distância, quando prevista no PDI"],"complementar":["Atas de colegiado que aprovaram mudanças curriculares no triênio","Editais de monitoria, de nivelamento e de mobilidade acadêmica","Convênios de mobilidade com instituições nacionais e internacionais"],"resultado":["Série de atualizações curriculares por curso no triênio, com data de aprovação","Indicador de participação em monitoria e nivelamento, com meta e realizado","Ação exitosa ou inovadora de ensino replicada em mais de um curso"]},"alerta":"Monitoria concentrada em uma área, sem alcance transversal aos cursos, fica em conceito 3. Na modalidade EaD a monitoria não é considerada: exigir monitoria de curso a distância é erro de leitura do instrumento."}'::jsonb),
  ('3.2','3','Políticas de ensino e ações acadêmico-administrativas para os cursos de pós-graduação lato sensu','NSA para faculdades e centros universitários, exceto quando houver previsão no PDI.','{"sinaes_dimension":2,"concept_descriptors":{"1":"As ações acadêmico-administrativas constantes do PDI não estão relacionadas com a política de ensino para os cursos de pós-graduação lato sensu.","2":"As ações acadêmico-administrativas constantes do PDI estão relacionadas com as políticas de ensino para os cursos de pós-graduação lato sensu, mas não se evidenciam a aprovação pelos colegiados da IES e o acompanhamento e a avaliação dos cursos ofertados.","3":"As ações acadêmico-administrativas constantes do PDI estão relacionadas com a política de ensino para os cursos de pós-graduação lato sensu, considerando a aprovação pelos colegiados da IES, o acompanhamento e a avaliação dos cursos ofertados, o atendimento às demandas socioeconômicas da região de inserção da IES e a articulação da oferta dos cursos lato sensu com as áreas da graduação. instrumento de avaliação institucional externa | presencial e A distância Recredenciamento | Transformação de Organização Acadêmica 16 CONCEITO CRITÉRIO DE ANÁLISE","4":"As ações acadêmico-administrativas constantes do PDI estão relacionadas com as políticas de ensino para os cursos de pós-graduação lato sensu, considerando a aprovação pelos colegiados da IES, o acompanhamento e a avaliação dos cursos ofertados, o atendimento às demandas socioeconômicas da região de inserção da IES e a articulação da oferta dos cursos lato sensu com as áreas da graduação; adicionalmente, mais de 50% dos docentes são mestres ou doutores.","5":"As ações acadêmico-administrativas constantes do PDI estão relacionadas com as políticas de ensino para os cursos de pós-graduação lato sensu, considerando a aprovação pelos colegiados da IES, o acompanhamento e a avaliação dos cursos ofertados, o atendimento às demandas socioeconômicas da região de inserção da IES e a articulação da oferta dos cursos lato sensu com as áreas da graduação; adicionalmente, mais de 50% dos docentes são mestres ou doutores e há outras ações reconhecidamente exitosas ou inovadoras."},"applicability":"NSA para faculdades e centros universitários, exceto quando houver previsão no PDI.","nota":null,"evidence":{"obrigatoria":["Política de pós-graduação lato sensu descrita no PDI","Ata de aprovação de cada curso lato sensu pelos colegiados da IES","Relatório de acompanhamento e avaliação dos cursos ofertados, com periodicidade","Quadro de titulação dos docentes do lato sensu, com comprovação de mais de 50% de mestres ou doutores","Estudo de demanda socioeconômica da região de inserção"],"complementar":["Matriz de articulação entre os cursos lato sensu e as áreas da graduação","Convênios e parcerias que sustentam a oferta","Pesquisa de egressos do lato sensu"],"resultado":["Série de matrícula e de conclusão por curso no triênio","Ajuste de oferta ou de projeto de curso tomado a partir da avaliação do curso"]},"alerta":"Curso lato sensu criado sem aprovação de colegiado e sem acompanhamento não conta, ainda que exista há anos. A titulação é condição cumulativa: sem os 50% de mestres e doutores, o indicador não fecha o 5 por mais completo que seja o resto."}'::jsonb),
  ('3.3','3','Políticas de ensino e ações acadêmico-administrativas para os cursos de pós-graduação stricto sensu','NSA para faculdades e centros universitários, exceto quando houver previsão no PDI.','{"sinaes_dimension":2,"concept_descriptors":{"1":"Não há política de ensino ou ações acadêmico-administrativas para os cursos de pós-graduação stricto sensu.","2":"As ações acadêmico-administrativas não estão relacionadas com a política de ensino para os cursos de pós-graduação stricto sensu, mas não há articulação com a graduação, por meio de grupos de estudo ou de pesquisa, de iniciação científica ou da atuação de professores dos programas de pós-graduação stricto sensu na graduação.","3":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de pós-graduação stricto sensu, considerando sua articulação com a graduação, por meio de grupos de estudo ou de pesquisa, de iniciação científica e da atuação de professores dos programas de pós-graduação stricto sensu na graduação.","4":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de pós-graduação stricto sensu, considerando sua articulação com a graduação, por meio de grupos de estudo ou de pesquisa, de iniciação científica e da atuação de professores dos programas de pós-graduação stricto sensu na graduação; adicionalmente, a IES possui pelo menos um programa de pós-graduação stricto sensu avaliado com conceito 5 pela CAPES.","5":"As ações acadêmico-administrativas estão relacionadas com a política de ensino para os cursos de pós-graduação stricto sensu, considerando sua articulação com a graduação, por meio de grupos de estudo ou de pesquisa, de iniciação científica e da atuação de professores dos programas de pós-graduação stricto sensu na graduação; adicionalmente, a IES possui pelo menos um programa de pós-graduação stricto sensu avaliado com conceito 6 ou 7 pela CAPES."},"applicability":"NSA para faculdades e centros universitários, exceto quando houver previsão no PDI.","nota":null,"evidence":{"obrigatoria":["Política de pós-graduação stricto sensu no PDI","Comprovação de articulação com a graduação: grupos de estudo ou de pesquisa, iniciação científica e atuação dos professores do stricto sensu na graduação","Documento da CAPES com o conceito do programa, quando existir"],"complementar":["Registro de disciplinas compartilhadas entre stricto sensu e graduação","Relatório de produção conjunta entre docentes do programa e graduandos"],"resultado":["Série de participação de graduandos em atividades do stricto sensu","Evolução do conceito CAPES no período, quando houver programa avaliado"]},"alerta":"O critério exige pelo menos um programa com conceito 6 ou 7 na CAPES. Sem esse patamar, o indicador para no conceito 4, ainda que a articulação com a graduação esteja bem documentada."}'::jsonb),
  ('3.4','3','Políticas institucionais e ações acadêmico-administrativas para a pesquisa ou iniciação científica, a inovação tecnológica e o desenvolvimento artístico e cultural','NSA para faculdades, exceto quando houver previsão no PDI.','{"sinaes_dimension":2,"concept_descriptors":{"1":"Não há ações acadêmico-administrativas para a pesquisa ou iniciação científica, a inovação tecnológica e o desenvolvimento artístico e cultural.","2":"As ações acadêmico-administrativas para a pesquisa ou iniciação científica, a inovação tecnológica e o desenvolvimento artístico e cultural não estão em conformidade com as políticas estabelecidas.","3":"As ações acadêmico-administrativas para a pesquisa ou iniciação científica, a inovação tecnológica e o desenvolvimento artístico e cultural estão em conformidade com as políticas estabelecidas, com garantia de sua divulgação no meio acadêmico.","4":"As ações acadêmico-administrativas para a pesquisa ou iniciação científica, a inovação tecnológica e o desenvolvimento artístico e cultural estão em conformidade com as políticas estabelecidas, com garantia de divulgação no meio acadêmico, e são estimuladas com programas de bolsas mantidos com recursos próprios ou de agências de fomento.","5":"As ações acadêmico-administrativas para a pesquisa ou iniciação científica, a inovação tecnológica e o desenvolvimento artístico e cultural estão em conformidade com as políticas estabelecidas, com garantia de divulgação no meio acadêmico, são estimuladas com programas de bolsas mantidos com recursos próprios ou de agências de fomento e promovem práticas reconhecidamente exitosas ou inovadoras."},"applicability":"NSA para faculdades, exceto quando houver previsão no PDI.","nota":null,"evidence":{"obrigatoria":["Política de pesquisa ou iniciação científica, inovação tecnológica e desenvolvimento artístico e cultural","Programa de bolsas com recursos próprios ou de agência de fomento, com edital e registro de concessão","Registro de divulgação dos resultados no meio acadêmico"],"complementar":["Relatório de projetos de pesquisa e de inovação em execução","Registro de produção artística e cultural do período"],"resultado":["Série de bolsas concedidas e de projetos concluídos no triênio","Prática exitosa ou inovadora reconhecida e documentada"]},"alerta":"Ação isolada, sem política escrita e sem bolsa, não sustenta o conceito 5. Divulgação apenas interna, sem registro de acesso, não comprova a garantia de divulgação exigida."}'::jsonb),
  ('3.5','3','Políticas institucionais e ações acadêmico-administrativas para a extensão',NULL,'{"sinaes_dimension":2,"concept_descriptors":{"1":"Não há ações acadêmico-administrativas para a extensão.","2":"As ações acadêmico-administrativas para a extensão não estão em conformidade com as políticas estabelecidas, considerando práticas efetivas para a melhoria das condições sociais da comunidade externa.","3":"As ações acadêmico-administrativas para a extensão estão em conformidade com as políticas estabelecidas, considerando práticas efetivas para a melhoria das condições sociais da comunidade externa, com garantia de divulgação no meio acadêmico.","4":"As ações acadêmico-administrativas para a extensão estão em conformidade com as políticas estabelecidas, considerando práticas efetivas para a melhoria das condições sociais da comunidade externa, com garantia de divulgação no meio acadêmico, e são estimuladas com programas de bolsas mantidos com recursos próprios ou de agências de fomento.","5":"As ações acadêmico-administrativas para a extensão estão em conformidade com as políticas estabelecidas, considerando práticas efetivas para a melhoria das condições sociais da comunidade externa, com garantia de divulgação no meio acadêmico, são estimuladas com programas de bolsas mantidos com recursos próprios ou de agências de fomento e promovem práticas reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de extensão aprovada pelo colegiado","Registro das práticas efetivas de extensão junto à comunidade externa, com público e território","Programa de bolsas de extensão com recursos próprios ou de agência de fomento","Registro de divulgação das ações no meio acadêmico"],"complementar":["Convênios com organizações da sociedade civil e com o poder público","Relatório de impacto das ações extensionistas"],"resultado":["Série de projetos, participantes e público alcançado no triênio","Evidência de melhoria das condições sociais da comunidade atendida"]},"alerta":"Extensão confundida com prestação de serviço remunerado ou com evento interno não atende ao critério. Sem prática efetiva com comunidade externa, o indicador não passa do conceito 3."}'::jsonb),
  ('3.6','3','Políticas institucionais e ações de estímulo e difusão para a produção acadêmica docente',NULL,'{"sinaes_dimension":2,"concept_descriptors":{"1":"Não há ações de estímulo e difusão para a produção acadêmica.","2":"As ações de estímulo e difusão para a produção acadêmica não promovem publicações científicas, didático-pedagógicas, tecnológicas, artísticas e culturais ou não incentivam a participação dos docentes em eventos locais.","3":"As ações de estímulo e difusão para a produção acadêmica promovem publicações científicas, didático-pedagógicas, tecnológicas, artísticas e culturais e incentivam a participação dos docentes em eventos de âmbito local e nacional.","4":"As ações de estímulo e difusão para a produção acadêmica promovem publicações científicas, didático-pedagógicas, tecnológicas, artísticas e culturais e incentivam a participação dos docentes em eventos de âmbito local, nacional e internacional.","5":"As ações de estímulo e difusão para a produção acadêmica promovem publicações científicas, didático-pedagógicas, tecnológicas, artísticas e culturais, incentivam a participação dos docentes em eventos de âmbito local, nacional e internacional, e incluem a organização e publicação de revista acadêmico-científica indexada no Qualis."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política institucional de estímulo e difusão da produção acadêmica docente","Registro das publicações docentes do triênio, com veículo e data","Comprovação de apoio à participação em eventos locais, nacionais e internacionais","Revista acadêmico-científica institucional com ISSN e comprovação de indexação no Qualis"],"complementar":["Editais de apoio à publicação e à tradução","Registro de organização de eventos científicos pela IES"],"resultado":["Série de publicações por docente e por veículo no triênio","Evolução do estrato Qualis da revista institucional"]},"alerta":"Revista sem indexação no Qualis não fecha o critério, ainda que publicada regularmente. Publicação dispersa, sem política de estímulo, conta apenas como produção, não como indicador institucional."}'::jsonb),
  ('3.7','3','Política institucional de acompanhamento dos egressos',NULL,'{"sinaes_dimension":9,"concept_descriptors":{"1":"Não há política institucional de acompanhamento dos egressos.","2":"A política institucional não garante mecanismo de acompanhamento de egressos.","3":"A política institucional garante mecanismo de acompanhamento de egressos e a atualização sistemática de informações a respeito da continuidade na vida acadêmica ou da inserção profissional.","4":"A política institucional garante mecanismo de acompanhamento de egressos, a atualização sistemática de informações a respeito da continuidade na vida acadêmica ou da inserção profissional e estudo comparativo entre a atuação do egresso e a formação recebida, subsidiando ações de melhoria relacionadas às demandas da sociedade e do mundo do trabalho.","5":"A política institucional garante mecanismo de acompanhamento de egressos, a atualização sistemática de informações a respeito da continuidade na vida acadêmica ou da inserção profissional, estudo comparativo entre a atuação do egresso e a formação recebida, subsidiando ações de melhoria relacionadas às demandas da sociedade e do mundo do trabalho, e promove outras ações reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política institucional de acompanhamento de egressos","Base de dados de egressos com rotina de atualização sistemática definida","Instrumento de coleta aplicado, com registro de período e de adesão","Estudo comparativo entre a atuação profissional do egresso e a formação recebida"],"complementar":["Pesquisa de empregabilidade e de continuidade na vida acadêmica","Encontros e associações de egressos com registro de participação"],"resultado":["Série de adesão ao acompanhamento e de inserção profissional no triênio","Ação de melhoria curricular ou de atendimento adotada a partir do que o egresso informou"]},"alerta":"Cadastro de egressos parado, sem atualização, não é acompanhamento. Sem o estudo comparativo entre atuação e formação, o indicador fica em conceito 4."}'::jsonb),
  ('3.8','3','Política institucional para internacionalização','NSA quando não houver previsão no PDI.','{"sinaes_dimension":2,"concept_descriptors":{"1":"A política institucional para a internacionalização não está articulada com o PDI.","2":"A política institucional para a internacionalização está articulada com o PDI, mas não apresenta atividades voltadas para programas de cooperação e intercâmbio.","3":"A política institucional para a internacionalização está articulada com o PDI e apresenta atividades voltadas para programas de cooperação e intercâmbio.","4":"A política institucional para a internacionalização está articulada com o PDI, apresenta atividades voltadas para programas de cooperação e intercâmbio e é coordenada por um grupo regulamentado.","5":"A política institucional para a internacionalização está articulada com o PDI, apresenta atividades voltadas para programas de cooperação e intercâmbio e é coordenada por um grupo regulamentado, responsável por sistematizar acordos e convênios internacionais de ensino e de mobilidade docente e discente."},"applicability":"NSA quando não houver previsão no PDI.","nota":null,"evidence":{"obrigatoria":["Política de internacionalização articulada ao PDI","Norma que cria e regulamenta o grupo coordenador da internacionalização","Registro dos acordos e convênios internacionais vigentes","Registro de atividades de cooperação e de intercâmbio"],"complementar":["Atas do grupo coordenador","Registro de mobilidade docente e discente, com destino e período"],"resultado":["Série de acordos ativos e de mobilidades realizadas no triênio","Evidência de sistematização de convênio que antes era informal"]},"alerta":"Convênio assinado e nunca executado não comprova política. Sem grupo regulamentado que sistematize os acordos, o indicador não passa do conceito 3."}'::jsonb),
  ('3.9','3','Comunicação da IES com a comunidade externa',NULL,'{"sinaes_dimension":4,"concept_descriptors":{"1":"Não há canais de comunicação externa.","2":"Os canais de comunicação externa divulgam informações de cursos, de programas, da extensão e da pesquisa (quando houver), mas não publicam documentos institucionais relevantes ou não possuem mecanismos de transparência institucional e de ouvidoria.","3":"Os canais de comunicação externa divulgam informações de cursos, de programas, da extensão e da pesquisa (quando houver), publicam documentos institucionais relevantes, possuem mecanismos de transparência institucional e de ouvidoria e permitem o acesso às informações acerca dos resultados da avaliação interna e externa.","4":"Os canais de comunicação externa divulgam informações de cursos, de programas, da extensão e da pesquisa (quando houver), publicam documentos institucionais relevantes, possuem mecanismos de transparência institucional e de ouvidoria, permitem o acesso às informações acerca dos resultados da avaliação interna e externa e apresentam instância específica que atua transversalmente às áreas.","5":"Os canais de comunicação externa divulgam informações de cursos, de programas, da extensão e da pesquisa (quando houver), publicam documentos institucionais relevantes, possuem mecanismos de transparência institucional e de ouvidoria, permitem o acesso às informações acerca dos resultados da avaliação interna e externa, apresentam instância específica que atua transversalmente às áreas e promovem outras ações reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de comunicação com a comunidade externa e mapa de canais com responsável","Comprovação de publicação de documentos institucionais relevantes","Norma e registro de funcionamento da ouvidoria","Comprovação de acesso público aos resultados das avaliações interna e externa","Norma que cria a instância transversal de comunicação"],"complementar":["Relatórios de audiência e de acesso aos canais","Registro de campanhas institucionais e de prestação de contas"],"resultado":["Série de demandas de ouvidoria recebidas e respondidas no prazo","Melhoria de canal ou de conteúdo adotada a partir de manifestação da comunidade"]},"alerta":"Site institucional desatualizado não cumpre transparência. Ouvidoria que existe no papel, sem registro de atendimento, derruba o indicador, e o mesmo se aplica a 3.10."}'::jsonb),
  ('3.10','3','Comunicação da IES com a comunidade interna',NULL,'{"sinaes_dimension":4,"concept_descriptors":{"1":"Não há comunicação da IES com a comunidade interna.","2":"A comunicação da IES com a comunidade interna não promove a transparência institucional, ou não divulga os resultados das avaliações interna e externa.","3":"A comunicação da IES com a comunidade interna promove a transparência institucional, divulga os resultados das avaliações interna e externa e disponibiliza ouvidoria.","4":"A comunicação da IES com a comunidade interna promove a transparência institucional, por meio de canais diversificados, impressos e virtuais, favorecendo o acesso por todos os segmentos da comunidade acadêmica, divulga os resultados das avaliações interna e externa e disponibiliza ouvidoria.","5":"A comunicação da IES com a comunidade interna promove a transparência institucional, por meio de canais diversificados, impressos e virtuais, favorecendo o acesso por todos os segmentos da comunidade acadêmica, divulga os resultados das avaliações interna e externa, disponibiliza ouvidoria e fomenta a manifestação da comunidade, gerando insumos para a melhoria da qualidade institucional."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de comunicação com a comunidade interna","Relação dos canais internos, impressos e virtuais, com periodicidade de uso","Comprovação de divulgação dos resultados das avaliações interna e externa","Registro de ouvidoria interna e de resposta às manifestações"],"complementar":["Boletins e informativos internos do triênio","Atas de reunião em que a manifestação da comunidade foi pauta"],"resultado":["Série de manifestações recebidas e de providências adotadas","Melhoria institucional documentada como resposta a insumo da comunidade interna"]},"alerta":"Canal que só informa, sem escuta, não atende ao critério. Sem prova de que a manifestação gerou insumo de melhoria, o indicador para no conceito 4."}'::jsonb),
  ('3.11','3','Política de atendimento aos discentes',NULL,'{"sinaes_dimension":9,"concept_descriptors":{"1":"Não há programas de apoio aos discentes.","2":"A política de atendimento aos discentes não contempla programas de acolhimento ao ingressante, programas de acessibilidade, monitoria ou nivelamento.","3":"A política de atendimento aos discentes contempla programas de acolhimento e permanência do discente, programas de acessibilidade, monitoria, nivelamento, intermediação e acompanhamento de estágios não obrigatórios remunerados, e apoio psicopedagógico.","4":"A política de atendimento aos discentes contempla programas de acolhimento e permanência do discente, programas de acessibilidade, monitoria, nivelamento, intermediação e acompanhamento de estágios não obrigatórios remunerados e apoio psicopedagógico, e apresenta uma instância que permite o atendimento discente em todos os setores pedagógico-administrativos da instituição.","5":"A política de atendimento aos discentes contempla programas de acolhimento e permanência do discente, programas de acessibilidade, monitoria, nivelamento, intermediação e acompanhamento de estágios não obrigatórios remunerados e apoio psicopedagógico, apresenta uma instância que permite o atendimento discente em todos os setores pedagógico-administrativos da instituição e promove outras ações reconhecidamente exitosas ou inovadoras."},"applicability":null,"nota":"Para a modalidade EaD, não considerar programas de monitoria.","evidence":{"obrigatoria":["Política de atendimento aos discentes aprovada pelo colegiado","Registro dos programas de acolhimento e de permanência","Registro do programa de acessibilidade e do apoio psicopedagógico, com equipe responsável","Registro de nivelamento e de intermediação de estágios não obrigatórios remunerados","Norma que cria a instância de atendimento transversal aos setores pedagógico-administrativos"],"complementar":["Relatórios de atendimento por tipo de demanda","Fluxo documentado de encaminhamento entre setores"],"resultado":["Série de atendimentos e de permanência no triênio","Redução de evasão ou de retenção atribuída ao programa, com dado de antes e depois"]},"alerta":"Atendimento concentrado na coordenação de curso, sem instância transversal, não atende ao critério. Programa criado no último ano do triênio não demonstra consolidação e fica em conceito 3."}'::jsonb),
  ('3.12','3','Políticas institucionais e ações de estímulo à produção discente e à participação em eventos (graduação e pós-graduação)',NULL,'{"sinaes_dimension":9,"concept_descriptors":{"1":"Não há políticas institucionais e ações de estímulo à produção discente e à participação em eventos.","2":"As políticas institucionais e ações de estímulo não garantem apoio financeiro ou logístico para a organização e participação em eventos na IES ou apoio à produção acadêmica discente.","3":"As políticas institucionais e ações de estímulo garantem apoio financeiro ou logístico para a organização e participação em eventos na IES e de âmbito local, e apoio à produção acadêmica discente.","4":"As políticas institucionais e ações de estímulo garantem apoio financeiro ou logístico para a organização e participação em eventos na IES e de âmbito local, nacional ou internacional, e apoio à produção acadêmica discente e à sua publicação em encontros e periódicos nacionais.","5":"As políticas institucionais e ações de estímulo garantem apoio financeiro ou logístico para a organização e participação em eventos na IES e de âmbito local, nacional ou internacional, e apoio à produção acadêmica discente e à sua publicação em encontros e periódicos nacionais e internacionais."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política institucional de estímulo à produção discente e à participação em eventos","Registro de apoio financeiro ou logístico concedido, com edital e prestação de contas","Comprovação de apoio à publicação discente em encontros e periódicos"],"complementar":["Relação de eventos realizados na IES com participação discente","Registro de trabalhos discentes apresentados e publicados"],"resultado":["Série de apoios concedidos e de trabalhos apresentados no triênio","Evidência de publicação discente em periódico nacional ou internacional"]},"alerta":"Apoio informal, decidido caso a caso e sem edital, não comprova política. Apoio restrito a eventos internos não atende ao critério, que exige âmbito local, nacional ou internacional."}'::jsonb),
  ('4.1','4','Titulação do corpo docente',NULL,'{"sinaes_dimension":5,"concept_descriptors":{"1":"O corpo docente é composto por menos de 25% de mestres e doutores.","2":"O corpo docente é composto por ao menos 25% de mestres e doutores.","3":"O corpo docente é composto por ao menos 40% de mestres e doutores.","4":"O corpo docente é composto por ao menos 60% de mestres e doutores.","5":"O corpo docente é composto por ao menos 80% de mestres e doutores."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Relatório de titulação do corpo docente, com nome, titulação e comprovação do diploma","Quadro de docentes vinculados ao período avaliado, com regime de trabalho"],"complementar":["Registro do censo da educação superior do período","Atas de colegiado que registram a composição do corpo docente"],"resultado":["Série do percentual de mestres e doutores nos três anos do triênio","Plano de qualificação que explique a evolução do percentual"]},"alerta":"O critério é numérico: ao menos 80% de mestres e doutores. Abaixo disso o indicador não fecha o 5, independentemente da qualidade do ensino. Docente com titulação declarada e sem comprovação não entra na conta."}'::jsonb),
  ('4.2','4','Política de capacitação docente e formação continuada',NULL,'{"sinaes_dimension":5,"concept_descriptors":{"1":"Não há política de capacitação docente e formação continuada.","2":"A política de capacitação docente e formação continuada não garante a participação em eventos científicos, técnicos, artísticos ou culturais ou em cursos de desenvolvimento pessoal e profissional.","3":"A política de capacitação docente e formação continuada garante a participação em eventos científicos, técnicos, artísticos ou culturais e em cursos de desenvolvimento pessoal e profissional.","4":"A política de capacitação docente e formação continuada garante a participação em eventos científicos, técnicos, artísticos ou culturais, em cursos de desenvolvimento pessoal e profissional e a qualificação acadêmica em programas de mestrado e doutorado.","5":"A política de capacitação docente e formação continuada garante a participação em eventos científicos, técnicos, artísticos ou culturais, em cursos de desenvolvimento pessoal e a qualificação acadêmica em programas de mestrado e doutorado, com práticas consolidadas, instituídas e publicizadas."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de capacitação docente e de formação continuada, aprovada e publicizada","Plano de capacitação do triênio com previsão orçamentária","Registro de participação em eventos científicos, técnicos, artísticos ou culturais","Registro de afastamentos e de apoio à qualificação em mestrado e doutorado"],"complementar":["Certificados e declarações de participação","Relatório de cursos de desenvolvimento pessoal ofertados"],"resultado":["Série de docentes capacitados e de horas de formação no triênio","Evolução da titulação docente atribuível ao plano de capacitação"]},"alerta":"Política que só consta do PDI, sem plano, orçamento e registro de execução, não é prática instituída. Participação isolada de um docente não comprova política institucional."}'::jsonb),
  ('4.3','4','Política de capacitação e formação continuada para o corpo técnico-administrativo',NULL,'{"sinaes_dimension":5,"concept_descriptors":{"1":"Não há política de capacitação e formação continuada para o corpo técnico-administrativo.","2":"A política de capacitação e formação continuada para o corpo técnico- administrativo não garante a participação em eventos científicos, técnicos, artísticos ou culturais e em cursos de desenvolvimento pessoal e profissional.","3":"A política de capacitação e formação continuada para o corpo técnico- administrativo garante a participação em eventos científicos, técnicos, artísticos ou culturais e em cursos de desenvolvimento pessoal e profissional.","4":"A política de capacitação e formação continuada para o corpo técnico- administrativo garante a participação em eventos científicos, técnicos, artísticos ou culturais, em cursos de desenvolvimento pessoal e profissional e a qualificação acadêmica na graduação e/ou em programas de pós-graduação.","5":"A política de capacitação e formação continuada para o corpo técnico- administrativo garante a participação em eventos científicos, técnicos, artísticos ou culturais, em cursos de desenvolvimento pessoal e profissional e a qualificação acadêmica na graduação e/ou em programas de pós- graduação, com práticas consolidadas e institucionalizadas."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Política de capacitação do corpo técnico-administrativo","Plano de capacitação com previsão orçamentária e calendário","Registro de participação em eventos científicos, técnicos, artísticos ou culturais","Registro de apoio à qualificação na graduação e na pós-graduação"],"complementar":["Levantamento de necessidades de formação por setor","Relatório de cursos de desenvolvimento pessoal e profissional"],"resultado":["Série de servidores capacitados e de horas de formação no triênio","Melhoria de processo administrativo atribuível à capacitação"]},"alerta":"Capacitação restrita a exigência legal de treinamento pontual não comprova política de formação continuada. Sem registro de execução no triênio, o indicador fica em conceito 3."}'::jsonb),
  ('4.4','4','Política de capacitação e formação continuada para o corpo de tutores presenciais e a distância','Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n° 1.134 de 10/10/2016.','{"sinaes_dimension":5,"concept_descriptors":{"1":"Não há política de capacitação e formação continuada para o corpo de tutores presenciais e a distância.","2":"A política de capacitação e formação continuada para o corpo de tutores presenciais e a distância não garante a participação em eventos científicos, técnicos, artísticos ou culturais e em cursos de desenvolvimento pessoal e profissional.","3":"A política de capacitação e formação continuada para o corpo de tutores presenciais e a distância garante a participação em eventos científicos, técnicos, artísticos ou culturais e em cursos de desenvolvimento pessoal e profissional.","4":"A política de capacitação e formação continuada para o corpo de tutores presenciais e a distância garante a participação em eventos científicos, técnicos, artísticos ou culturais, em cursos de desenvolvimento pessoal e profissional e a qualificação acadêmica em graduação e/ou programas de pós-graduação.","5":"A política de capacitação e formação continuada para o corpo de tutores presenciais e a distância garante a participação em eventos científicos, técnicos, artísticos ou culturais, em cursos de desenvolvimento pessoal e profissional e a qualificação acadêmica em graduação e/ou programas de pós-graduação, com práticas consolidadas e institucionalizadas."},"applicability":"Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n° 1.134 de 10/10/2016.","nota":null,"evidence":{"obrigatoria":["Política de capacitação do corpo de tutores presenciais e a distância","Plano de formação inicial e continuada de tutores, com carga horária","Registro de participação dos tutores em eventos e cursos","Registro de apoio à qualificação em graduação e pós-graduação"],"complementar":["Material didático dos cursos de formação de tutores","Avaliação de desempenho dos tutores vinculada à formação"],"resultado":["Série de tutores capacitados no triênio","Efeito da formação no desempenho da tutoria, com dado de antes e depois"]},"alerta":"Formação inicial obrigatória, aplicada só na admissão, não é formação continuada. Tutor contratado e não capacitado no período reprova o critério."}'::jsonb),
  ('4.5','4','Processos de gestão institucional',NULL,'{"sinaes_dimension":6,"concept_descriptors":{"1":"Os processos de gestão institucional não consideram a autonomia e a representatividade dos órgãos gestores e colegiados ou a participação de docentes, técnicos, discentes, da sociedade civil organizada e dos tutores (estes, quando for o caso).","2":"Os processos de gestão institucional consideram a autonomia e a representatividade dos órgãos gestores e colegiados e a participação de docentes, técnicos, discentes, da sociedade civil organizada e dos tutores (estes, quando for o caso), mas não regulamentam o mandato dos membros que compõem os órgãos colegiados.","3":"Os processos de gestão institucional consideram a autonomia e a representatividade dos órgãos gestores e colegiados e a participação de docentes, técnicos, discentes, da sociedade civil organizada e dos tutores (estes, quando for o caso), e regulamentam o mandato dos membros que compõem os órgãos colegiados.","4":"Os processos de gestão institucional consideram a autonomia e a representatividade dos órgãos gestores e colegiados e a participação de docentes, técnicos, discentes e da sociedade civil organizada e dos tutores (estes, quando for o caso), regulamentam o mandato dos membros que compõem os órgãos colegiados e sistematizam e divulgam as decisões colegiadas.","5":"Os processos de gestão institucional consideram a autonomia e a representatividade dos órgãos gestores e colegiados e a participação de docentes, técnicos, discentes e da sociedade civil organizada e dos tutores (estes, quando for o caso), regulamentam o mandato dos membros que compõem os órgãos colegiados e sistematizam e divulgam as decisões colegiadas, cuja apropriação pela comunidade interna é assegurada."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Estatuto ou regimento com a composição e a competência dos órgãos gestores e colegiados","Norma que regulamenta o mandato dos membros dos colegiados","Registro da participação de docentes, técnicos, discentes e sociedade civil organizada, e de tutores quando for o caso","Sistema de registro e divulgação das decisões colegiadas"],"complementar":["Atas de reunião dos colegiados do triênio","Registro de autonomia orçamentária e decisória dos órgãos","Comprovação de que a comunidade interna conhece as decisões"],"resultado":["Série de reuniões e de deliberações por colegiado no triênio","Decisão colegiada que alterou efetivamente a gestão, com efeito documentado"]},"alerta":"Colegiado que existe no regimento e não se reúne, ou que só referenda o que já foi decidido, não atende ao critério. Mandato sem norma de renovação derruba o indicador."}'::jsonb),
  ('4.6','4','Sistema de controle de produção e distribuição de material didático','Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n°1.134 de 10/10/2016.','{"sinaes_dimension":6,"concept_descriptors":{"1":"O sistema de controle e distribuição de material didático não está formalizado.","2":"O sistema de controle de produção e distribuição de material didático não considera o atendimento da demanda, a existência de uma equipe técnica multidisciplinar responsável ou estratégias que garantem a acessibilidade comunicacional.","3":"O sistema de controle de produção e distribuição de material didático considera o atendimento da demanda, a existência de uma equipe técnica multidisciplinar responsável e estratégias que garantem a acessibilidade comunicacional.","4":"O sistema de controle de produção e distribuição de material didático considera o atendimento da demanda, a existência de uma equipe técnica multidisciplinar responsável, estratégias que garantem a acessibilidade comunicacional e disponibilização por diferentes mídias, suportes e linguagens.","5":"O sistema de controle de produção e distribuição de material didático considera o atendimento da demanda, a existência de uma equipe técnica multidisciplinar responsável, estratégias que garantem a acessibilidade comunicacional, disponibilização por diferentes mídias, suportes e linguagens, plano de atualização do material didático e apoio à produção de material autoral pelo corpo docente."},"applicability":"Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n°1.134 de 10/10/2016.","nota":null,"evidence":{"obrigatoria":["Sistema de controle de produção e distribuição de material didático documentado","Equipe técnica multidisciplinar designada, com funções definidas","Estudo de atendimento da demanda de material didático","Plano de atualização do material didático","Comprovação de acessibilidade comunicacional do material e de oferta em diferentes mídias"],"complementar":["Registro de apoio à produção de material autoral pelo corpo docente","Relatório de distribuição por curso e por polo"],"resultado":["Série de material produzido e atualizado no triênio","Indicador de atendimento da demanda, com meta e realizado"]},"alerta":"Material produzido caso a caso, sem sistema de controle e sem equipe designada, não comprova o critério. Acessibilidade declarada sem prova no material entregue não conta."}'::jsonb),
  ('4.7','4','Sustentabilidade financeira: relação com o desenvolvimento institucional',NULL,'{"sinaes_dimension":10,"concept_descriptors":{"1":"O orçamento não é formulado a partir do PDI.","2":"O orçamento é formulado a partir do PDI e está de acordo com as políticas de ensino, extensão e pesquisa (quando for o caso).","3":"O orçamento é formulado a partir do PDI, está de acordo com as políticas de ensino, extensão e pesquisa (quando for o caso) e prevê ampliação e fortalecimento de fontes captadoras de recursos.","4":"O orçamento é formulado a partir do PDI, está de acordo com as políticas de ensino, extensão e pesquisa (quando for o caso), prevê ampliação e fortalecimento de fontes captadoras de recursos e apresenta estudos para monitoramento e acompanhamento da distribuição de créditos.","5":"O orçamento é formulado a partir do PDI, está de acordo com as políticas de ensino, extensão e pesquisa (quando for o caso), prevê ampliação e fortalecimento de fontes captadoras de recursos e apresenta estudos para monitoramento e acompanhamento da distribuição de créditos, com metas objetivas e mensuráveis, por meio de indicadores de desempenho institucionalizados."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Orçamento do triênio formulado a partir do PDI","Demonstração do alinhamento orçamentário com as políticas de ensino, extensão e pesquisa","Plano de ampliação e fortalecimento das fontes de captação de recursos","Indicadores de desempenho institucionalizados para monitorar a distribuição de créditos"],"complementar":["Prestação de contas e balanços do período","Relatório de execução orçamentária por área","Estudos de monitoramento da distribuição de créditos"],"resultado":["Série de execução orçamentária contra o previsto no PDI, no triênio","Ampliação efetiva de fonte de captação, com valor e data"]},"alerta":"Orçamento que segue a receita e não o PDI inverte o critério. Metas sem indicador institucionalizado não comprovam monitoramento, e o indicador para no conceito 4."}'::jsonb),
  ('4.8','4','Sustentabilidade financeira: participação da comunidade interna',NULL,'{"sinaes_dimension":10,"concept_descriptors":{"1":"O orçamento não dispõe de acompanhamento ou participação das instâncias gestoras e acadêmicas.","2":"O orçamento dispõe de acompanhamento ou participação das instâncias gestoras e acadêmicas.","3":"O orçamento dispõe de ciência, participação e acompanhamento das instâncias gestoras e acadêmicas, orientando a tomada de decisões internas.","4":"O orçamento considera as análises do relatório de avaliação interna e dispõe de ciência, participação e acompanhamento das instâncias gestoras e acadêmicas, orientando a tomada de decisões internas.","5":"O orçamento considera as análises do relatório de avaliação interna e dispõe de ciência, participação e acompanhamento das instâncias gestoras e acadêmicas (estas, capacitadas para a gestão de recursos), orientando a tomada de decisões internas."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Comprovação de que o orçamento considera as análises do relatório de avaliação interna","Registro de ciência e participação das instâncias gestoras e acadêmicas na elaboração orçamentária","Comprovação de capacitação das instâncias acadêmicas para a gestão de recursos","Registro de decisão interna orientada pelo orçamento"],"complementar":["Atas das instâncias que analisaram o orçamento","Material de capacitação em gestão de recursos"],"resultado":["Série de decisões de alocação tomadas com participação das instâncias no triênio","Realocação de recurso motivada por resultado da avaliação interna"]},"alerta":"Orçamento aprovado apenas pela mantenedora, sem participação das instâncias acadêmicas, não atende ao critério. Ciência sem participação não é participação."}'::jsonb),
  ('5.1','5','Instalações administrativas',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"As instalações administrativas não atendem às necessidades institucionais.","2":"As instalações administrativas atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"As instalações administrativas atendem às necessidades institucionais, considerando a sua adequação às atividades, a guarda, manutenção e disponibilização de documentação acadêmica, a acessibilidade e a avaliação periódica dos espaços.","4":"As instalações administrativas atendem às necessidades institucionais, considerando a sua adequação às atividades, a guarda, manutenção e disponibilização de documentação acadêmica, a acessibilidade, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial.","5":"As instalações administrativas atendem às necessidades institucionais, considerando a sua adequação às atividades, a guarda, manutenção e disponibilização de documentação acadêmica, a acessibilidade, a avaliação periódica dos espaços, o gerenciamento da manutenção patrimonial e a existência de recursos tecnológicos diferenciados."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Planta baixa das instalações administrativas com destinação de cada setor","Norma de guarda, manutenção e disponibilização da documentação acadêmica","Relatório de acessibilidade física das instalações administrativas","Registro da avaliação periódica dos espaços, com data e responsável","Plano e registro de manutenção patrimonial das instalações"],"complementar":["Inventário dos recursos tecnológicos disponíveis nos setores administrativos","Registro fotográfico datado das instalações","Relatório de adequação dos mobiliários às atividades"],"resultado":["Série de avaliações dos espaços no triênio, com achado e providência","Melhoria de instalação executada a partir da avaliação periódica","Tempo médio de recuperação de documento acadêmico solicitado, com série"]},"alerta":"Instalação adequada e sem avaliação periódica registrada segura o indicador no conceito 4. Documentação acadêmica guardada em local improvisado, sem norma de guarda, reprova o critério ainda que o espaço seja bom."}'::jsonb),
  ('5.2','5','Salas de aula','NSA para a modalidade a distância quando não houver previsão de atividades presenciais.','{"sinaes_dimension":7,"concept_descriptors":{"1":"As salas de aula não atendem às necessidades institucionais.","2":"As salas de aula atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"As salas de aula atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade e a avaliação periódica dos espaços.","4":"As salas de aula atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas.","5":"As salas de aula atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços, o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas, e a existência de recursos tecnológicos diferenciados."},"applicability":"NSA para a modalidade a distância quando não houver previsão de atividades presenciais.","nota":null,"evidence":{"obrigatoria":["Relação das salas de aula com capacidade, metragem e curso atendido","Laudo ou relatório de acessibilidade das salas","Registro da avaliação periódica das salas, com data e responsável","Norma de manutenção patrimonial e registro de execução","Inventário dos recursos tecnológicos diferenciados instalados"],"complementar":["Registro fotográfico datado por sala","Plano de adequação de salas por curso","Relatório de conforto ambiental e ergonômico"],"resultado":["Série de avaliações das salas no triênio, com achado e providência","Melhoria de sala executada e seu efeito na atividade didática","Taxa de ocupação contra capacidade instalada, com análise"]},"alerta":"Sala em uso, mas sem norma consolidada de avaliação e manutenção, fica em conceito 3. Grupo de salas reformadas no último ano não demonstra institucionalização se não houver série anterior."}'::jsonb),
  ('5.3','5','Auditório(s)','NSA para a modalidade a distância quando não houver previsão de atividades presenciais.','{"sinaes_dimension":7,"concept_descriptors":{"1":"Não há auditório(s).","2":"O(s) auditório(s) não atende(m) às necessidades institucionais.","3":"O(s) auditório(s) atende(m) às necessidades institucionais, considerando a acessibilidade, o conforto, o isolamento e a qualidade acústica.","4":"O(s) auditório(s) atende(m) às necessidades institucionais, considerando a acessibilidade, o conforto, o isolamento e a qualidade acústica e, em pelo menos um auditório, a existência de recursos tecnológicos multimídia, incluindo-se a disponibilidade de conexão à internet.","5":"O(s) auditório(s) atende(m) às necessidades institucionais, considerando a acessibilidade, o conforto, o isolamento e a qualidade acústica e, em pelo menos um auditório, a existência de recursos tecnológicos multimídia, incluindo-se a disponibilidade de conexão à internet e de equipamentos para videoconferência."},"applicability":"NSA para a modalidade a distância quando não houver previsão de atividades presenciais.","nota":null,"evidence":{"obrigatoria":["Relação dos auditórios com capacidade e metragem","Laudo de acessibilidade e de conforto acústico","Inventário dos recursos multimídia, incluindo conexão à internet e equipamentos de videoconferência","Registro de uso dos auditórios pela comunidade acadêmica"],"complementar":["Registro fotográfico datado","Agenda de eventos realizados no período","Relatório de isolamento acústico"],"resultado":["Série de eventos e de público atendido no triênio","Melhoria acústica ou multimídia executada a partir de medição","Indicador de disponibilidade dos equipamentos de videoconferência"]},"alerta":"Auditório sem pelo menos um espaço com recursos multimídia completos não atende ao critério. Conforto e acústica declarados sem medição não comprovam a condição."}'::jsonb),
  ('5.4','5','Sala de professores',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"As salas de professores não atendem às necessidades institucionais.","2":"As salas de professores atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"As salas de professores atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade e a avaliação periódica dos espaços.","4":"As salas de professores atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas.","5":"As salas de professores atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços, o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas, e a existência de recursos tecnológicos diferenciados."},"applicability":null,"nota":"Para a modalidade a distância, considerar as salas de professores e ou de tutores.","evidence":{"obrigatoria":["Relação das salas de professores e de tutores com capacidade","Laudo ou relatório de acessibilidade","Registro da avaliação periódica dos espaços","Norma de manutenção patrimonial e registro de execução","Inventário dos recursos tecnológicos diferenciados disponíveis"],"complementar":["Registro fotográfico datado","Registro de uso por turno e por curso","Relatório de mobiliário e de ergonomia"],"resultado":["Série de avaliações dos espaços no triênio","Melhoria executada a partir da avaliação, com efeito na permanência docente","Indicador de adequação do espaço ao número de professores em atividade"]},"alerta":"Sala de professores existente, mas sem avaliação periódica e sem norma de manutenção, fica em conceito 3. Na modalidade a distância, ignorar a sala de tutores reprova o indicador mesmo com a sala de professores adequada."}'::jsonb),
  ('5.5','5','Espaços para atendimento aos discentes','NSA para a modalidade a distância quando não houver previsão de atividades presenciais.','{"sinaes_dimension":7,"concept_descriptors":{"1":"Os espaços para atendimento aos discentes não atendem às necessidades institucionais.","2":"Os espaços para atendimento aos discentes atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"Os espaços para atendimento aos discentes atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade e a avaliação periódica dos espaços. instrumento de avaliação institucional externa | presencial e A distância Recredenciamento | Transformação de Organização Acadêmica 27 27 CONCEITO CRITÉRIO DE ANÁLISE","4":"Os espaços para atendimento aos discentes atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas.","5":"Os espaços para atendimento aos discentes atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços, o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas, e a possibilidade de implementação de variadas formas de atendimento."},"applicability":"NSA para a modalidade a distância quando não houver previsão de atividades presenciais.","nota":null,"evidence":{"obrigatoria":["Relação dos espaços de atendimento ao discente, com localização e capacidade","Laudo ou relatório de acessibilidade","Registro da avaliação periódica dos espaços","Norma de manutenção patrimonial e registro de execução","Documento que descreve as formas de atendimento implantadas"],"complementar":["Registro fotográfico datado","Fluxo de encaminhamento do discente entre setores","Relatório de demanda de atendimento por tipo"],"resultado":["Série de atendimentos realizados por espaço no triênio","Ampliação das formas de atendimento, com data e alcance","Melhoria de espaço executada a partir da avaliação periódica"]},"alerta":"Balcão único sem privacidade e sem possibilidade de outras formas de atendimento não atende ao critério. Espaço adequado e sem registro de avaliação periódica para no conceito 4."}'::jsonb),
  ('5.6','5','Espaços de convivência e de alimentação',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"Os espaços de convivência e de alimentação não atendem às necessidades institucionais.","2":"Os espaços de convivência e de alimentação atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"Os espaços de convivência e de alimentação atendem às necessidades institucionais, considerando a sua adequação às atividades, as condições de limpeza e segurança, a acessibilidade e a avaliação periódica dos espaços.","4":"Os espaços de convivência e de alimentação atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços e a dimensão necessária para integração entre os membros da comunidade acadêmica.","5":"Os espaços de convivência e de alimentação atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, a avaliação periódica dos espaços, a dimensão necessária para integração entre os membros da comunidade acadêmica e a existência de serviços variados e adequados."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Relação dos espaços de convivência e de alimentação, com metragem e capacidade","Laudo ou relatório de acessibilidade","Registro da avaliação periódica dos espaços","Contratos ou registros dos serviços de alimentação disponíveis"],"complementar":["Registro fotográfico datado","Pesquisa de satisfação da comunidade acadêmica sobre os espaços","Relatório de dimensionamento do espaço contra o número de usuários"],"resultado":["Série de avaliações dos espaços no triênio","Ampliação ou melhoria executada a partir da avaliação","Indicador de uso dos espaços, com meta e realizado"]},"alerta":"Espaço de convivência reduzido ou sem serviço de alimentação, quando há previsão no PDI, não fecha o critério. A dimensão do espaço precisa ser demonstrada contra o público real, não apenas declarada."}'::jsonb),
  ('5.7','5','Laboratórios, ambientes e cenários para práticas didáticas: infraestrutura física','NSA para a modalidade a distância quando não houver previsão de atividades presenciais.','{"sinaes_dimension":7,"concept_descriptors":{"1":"Os laboratórios, ambientes e cenários para práticas didáticas não atendem às necessidades institucionais.","2":"Os laboratórios, ambientes e cenários para práticas didáticas atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"Os laboratórios, ambientes e cenários para práticas didáticas atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, as normas de segurança e a avaliação periódica dos espaços.","4":"Os laboratórios, ambientes e cenários para práticas didáticas atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, as normas de segurança, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas.","5":"Os laboratórios, ambientes e cenários para práticas didáticas atendem às necessidades institucionais, considerando a sua adequação às atividades, a acessibilidade, as normas de segurança, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas, e a existência de recursos tecnológicos diferenciados."},"applicability":"NSA para a modalidade a distância quando não houver previsão de atividades presenciais.","nota":null,"evidence":{"obrigatoria":["Relação dos laboratórios e cenários de prática, com capacidade e curso atendido","Laudo de acessibilidade e de conformidade com as normas de segurança","Registro da avaliação periódica dos espaços","Norma de manutenção patrimonial e registro de execução","Inventário dos recursos tecnológicos diferenciados"],"complementar":["Registro fotográfico datado","Manual de uso e de segurança dos laboratórios","Registro de manutenção de equipamentos e de calibração"],"resultado":["Série de avaliações dos laboratórios no triênio","Melhoria executada a partir da avaliação, com efeito na prática didática","Indicador de disponibilidade dos equipamentos, com meta e realizado"]},"alerta":"Laboratório em funcionamento sem laudo de segurança e sem avaliação periódica reprova o critério. Equipamento parado por falta de manutenção derruba o indicador mesmo com o espaço adequado."}'::jsonb),
  ('5.8','5','Infraestrutura física e tecnológica destinada à CPA',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"Não há infraestrutura física ou tecnológica destinada à CPA.","2":"A infraestrutura física e tecnológica destinada à CPA não atende às necessidades institucionais.","3":"A infraestrutura física e tecnológica destinada à CPA atende às necessidades institucionais, considerando o espaço de trabalho para seus membros e as condições físicas e de tecnologia da informação para a coleta e análise de dados.","4":"A infraestrutura física e tecnológica destinada à CPA atende às necessidades institucionais, considerando o espaço de trabalho para seus membros, as condições físicas e de tecnologia da informação para a coleta e análise de dados e os recursos tecnológicos para implantação da metodologia escolhida para o processo de autoavaliação.","5":"A infraestrutura física e tecnológica destinada à CPA atende às necessidades institucionais, considerando o espaço de trabalho para seus membros, as condições físicas e de tecnologia da informação para a coleta e análise de dados, os recursos tecnológicos para implantação da metodologia escolhida para o processo de autoavaliação e recursos ou processos comprovadamente inovadores."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Identificação do espaço físico destinado à CPA, com metragem","Inventário dos recursos de tecnologia da informação disponíveis à CPA","Documento que descreve a metodologia de autoavaliação e os recursos tecnológicos para implantá-la","Registro de acesso da CPA ao sistema acadêmico e às bases de dados institucionais"],"complementar":["Registro fotográfico datado do espaço","Relatório de recursos ou processos inovadores usados pela CPA","Ata da CPA que registra a adequação do espaço"],"resultado":["Série de coletas e análises realizadas pela CPA com os recursos disponíveis","Melhoria do espaço ou da ferramenta executada a partir de demanda da CPA","Tempo de produção do relatório de autoavaliação, com série"]},"alerta":"CPA que funciona na sala de outro setor, sem espaço próprio e sem acesso a dados, não atende ao critério. Recurso tecnológico declarado e não utilizado pela CPA não comprova a condição."}'::jsonb),
  ('5.9','5','Bibliotecas: infraestrutura','NSA para a modalidade a distância quando não houver previsão de atividades presenciais.','{"sinaes_dimension":7,"concept_descriptors":{"1":"A infraestrutura para bibliotecas não atende às necessidades institucionais.","2":"A infraestrutura para bibliotecas atende às necessidades institucionais, mas não apresenta acessibilidade, ou não possui estações individuais e coletivas para estudos ou recursos tecnológicos para consulta, guarda, empréstimo e organização do acervo.","3":"A infraestrutura para bibliotecas atende às necessidades institucionais, apresenta acessibilidade, e possui estações individuais e coletivas para estudos e recursos tecnológicos para consulta, guarda, empréstimo e organização do acervo.","4":"A infraestrutura para bibliotecas atende às necessidades institucionais, apresenta acessibilidade, possui estações individuais e coletivas para estudos e recursos tecnológicos para consulta, guarda, empréstimo e organização do acervo e fornece condições para atendimento educacional especializado.","5":"A infraestrutura para bibliotecas atende às necessidades institucionais, apresenta acessibilidade, possui estações individuais e coletivas para estudos e recursos tecnológicos para consulta, guarda, empréstimo e organização do acervo, fornece condições para atendimento educacional especializado e disponibiliza recursos comprovadamente inovadores."},"applicability":"NSA para a modalidade a distância quando não houver previsão de atividades presenciais.","nota":null,"evidence":{"obrigatoria":["Relação das bibliotecas com metragem, acervo e horário de funcionamento","Laudo ou relatório de acessibilidade física e comunicacional","Relação das estações individuais e coletivas de estudo","Sistema de consulta, guarda, empréstimo e organização do acervo, com registro de uso","Comprovação de condições para atendimento educacional especializado"],"complementar":["Registro fotográfico datado","Relatório de recursos comprovadamente inovadores disponíveis","Pesquisa de satisfação dos usuários"],"resultado":["Série de uso do acervo e de empréstimos no triênio","Melhoria executada a partir da avaliação dos usuários","Indicador de disponibilidade do sistema de consulta, com meta e realizado"]},"alerta":"Biblioteca com acervo bom e sem acessibilidade comprovada não fecha o critério. Estação de estudo inexistente ou insuficiente para o público real segura o indicador no conceito 4."}'::jsonb),
  ('5.10','5','Bibliotecas: plano de atualização do acervo',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"Não há plano de atualização do acervo descrito no PDI.","2":"Há plano de atualização do acervo descrito no PDI, mas não há viabilidade para sua execução.","3":"Há plano de atualização do acervo descrito no PDI, e viabilidade para sua execução, considerando a alocação de recursos.","4":"Há plano de atualização do acervo descrito no PDI, e viabilidade para sua execução, considerando a alocação de recursos e ações corretivas associadas ao acompanhamento e à avaliação do acervo pela comunidade acadêmica.","5":"Há plano de atualização do acervo descrito no PDI, e viabilidade para sua execução, considerando a alocação de recursos, ações corretivas associadas ao acompanhamento e à avaliação do acervo pela comunidade acadêmica e a existência de dispositivos inovadores."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Plano de atualização do acervo descrito no PDI","Demonstração da alocação de recursos prevista para o plano","Registro do acompanhamento e da avaliação do acervo pela comunidade acadêmica","Ações corretivas associadas ao acompanhamento do acervo"],"complementar":["Relatório de aquisições do triênio por área","Registro de dispositivos inovadores de acesso ao acervo","Comparação entre o acervo e a bibliografia dos PPC"],"resultado":["Série de execução do plano contra o previsto, no triênio","Ação corretiva executada a partir da avaliação do acervo, com efeito medido","Indicador de adequação do acervo à bibliografia básica e complementar"]},"alerta":"Plano descrito no PDI e nunca executado reprova o critério. Acervo atualizado sem participação da comunidade na avaliação fica em conceito 4."}'::jsonb),
  ('5.11','5','Salas de apoio de informática ou estrutura equivalente',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"As salas de apoio de informática ou estrutura equivalente não atendem às necessidades institucionais","2":"As salas de apoio de informática ou estrutura equivalente atendem às necessidades institucionais, considerando os equipamentos, as normas de segurança, o espaço físico, o acesso à internet, a atualização de softwares, a acessibilidade, os serviços e o suporte.","3":"As salas de apoio de informática ou estrutura equivalente atendem às necessidades institucionais, considerando os equipamentos, as normas de segurança, o espaço físico, o acesso à internet, a atualização de softwares, a acessibilidade, os serviços, o suporte e as condições ergonômicas.","4":"As salas de apoio de informática ou estrutura equivalente atendem às necessidades institucionais, considerando os equipamentos, as normas de segurança, o espaço físico, o acesso à internet, a atualização de softwares, a acessibilidade (incluindo recursos tecnológicos transformadores), os serviços, o suporte e as condições ergonômicas.","5":"As salas de apoio de informática ou estrutura equivalente atendem às necessidades institucionais, considerando os equipamentos, as normas de segurança, o espaço físico, o acesso à internet, a atualização de softwares, a acessibilidade (incluindo recursos tecnológicos transformadores), os serviços, o suporte, as condições ergonômicas e a oferta de recursos de informática comprovadamente inovadores."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Relação das salas de apoio de informática, com capacidade e equipamentos","Laudo de acessibilidade, incluindo recursos tecnológicos transformadores","Norma de segurança e de atualização de softwares","Registro de acesso à internet e de suporte técnico disponível","Registro de avaliação das condições ergonômicas"],"complementar":["Registro fotográfico datado","Relatório de manutenção e de renovação dos equipamentos","Relação dos serviços ofertados nas salas"],"resultado":["Série de uso das salas no triênio","Melhoria executada a partir da avaliação, com efeito no acesso","Indicador de disponibilidade dos equipamentos e de atualização de software"]},"alerta":"Sala com equipamentos obsoletos e sem plano de atualização não atende ao critério. Acessibilidade digital declarada sem recurso transformador instalado não conta."}'::jsonb),
  ('5.12','5','Instalações sanitárias',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"As instalações sanitárias não atendem às necessidades institucionais.","2":"As instalações sanitárias atendem às necessidades institucionais, considerando apenas a sua adequação às atividades.","3":"As instalações sanitárias atendem às necessidades institucionais, considerando a sua adequação às atividades, as condições de limpeza e segurança, a acessibilidade e a avaliação periódica dos espaços.","4":"As instalações sanitárias atendem às necessidades institucionais, considerando a sua adequação às atividades, as condições de limpeza e segurança, a acessibilidade, a avaliação periódica dos espaços e o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas.","5":"As instalações sanitárias atendem às necessidades institucionais, considerando a sua adequação às atividades, as condições de limpeza e segurança, a acessibilidade, a avaliação periódica dos espaços, o gerenciamento da manutenção patrimonial, com normas consolidadas e institucionalizadas, e a existência de banheiros familiares e fraldários."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Relação das instalações sanitárias com quantidade e localização","Laudo de acessibilidade","Registro das condições de limpeza e de segurança, com periodicidade","Registro da avaliação periódica dos espaços","Norma de manutenção patrimonial e registro de execução"],"complementar":["Registro fotográfico datado","Comprovação de existência de banheiros familiares e de fraldários","Relatório de adequação ao público real da IES"],"resultado":["Série de avaliações das instalações no triênio","Melhoria executada a partir da avaliação, com data","Indicador de conformidade das condições de limpeza, com meta e realizado"]},"alerta":"A ausência de banheiro familiar e de fraldário impede o conceito 5, ainda que as demais condições estejam atendidas. Limpeza declarada sem registro periódico não comprova a condição."}'::jsonb),
  ('5.13','5','Estrutura dos polos EAD','Exclusivo para modalidade a distância com previsão de oferta em polos. As informações dos polos devem estar disponíveis na sede da Instituição.','{"sinaes_dimension":7,"concept_descriptors":{"1":"A estrutura física, tecnológica e de pessoal nos polos não permite a execução das atividades previstas no PDI.","2":"A estrutura física, tecnológica e de pessoal nos polos permite a execução das atividades previstas no PDI, mas não viabiliza a realização das atividades presenciais, não apresenta acessibilidade ou não é adequada ao projeto pedagógico dos cursos vinculados.","3":"A estrutura física, tecnológica e de pessoal nos polos permite a execução das atividades previstas no PDI, viabiliza a realização das atividades presenciais, apresenta acessibilidade e é adequada ao projeto pedagógico dos cursos vinculados.","4":"A estrutura física, tecnológica e de pessoal nos polos permite a execução das atividades previstas no PDI, viabiliza a realização das atividades presenciais, apresenta acessibilidade, é adequada ao projeto pedagógico dos cursos vinculados, propicia interação entre docentes, tutores e discentes e possui modelos tecnológicos e digitais diferenciados aplicados aos processos de ensino e aprendizagem.","5":"A estrutura física, tecnológica e de pessoal nos polos permite a execução das atividades previstas no PDI, viabiliza a realização das atividades presenciais, apresenta acessibilidade, é adequada ao projeto pedagógico dos cursos vinculados, propicia interação entre docentes, tutores e discentes e possui modelos tecnológicos e digitais aplicados aos processos de ensino e aprendizagem e diferenciais inovadores comprovadamente exitosos."},"applicability":"Exclusivo para modalidade a distância com previsão de oferta em polos. As informações dos polos devem estar disponíveis na sede da Instituição.","nota":null,"evidence":{"obrigatoria":["Relação dos polos com endereço, estrutura física e equipe","Comprovação de que a estrutura permite executar as atividades previstas no PDI","Laudo de acessibilidade de cada polo","Demonstração de adequação ao projeto pedagógico dos cursos vinculados","Registro dos modelos tecnológicos e digitais aplicados ao ensino nos polos"],"complementar":["Registro fotográfico datado por polo","Escala de docentes e tutores por polo","Relatório de interação entre docentes, tutores e discentes"],"resultado":["Série de atividades presenciais realizadas por polo no triênio","Indicador de uso da estrutura por polo, com meta e realizado","Diferencial inovador comprovadamente exitoso, com resultado documentado"]},"alerta":"Polo com estrutura física e sem equipe, ou com equipe e sem estrutura, reprova o critério. Informação dos polos indisponível na sede impede a verificação e derruba o indicador."}'::jsonb),
  ('5.14','5','Infraestrutura tecnológica','Exclusivo para IES que preveem em seu PDI a adoção de metodologia baseada em recursos da Internet.','{"sinaes_dimension":7,"concept_descriptors":{"1":"Não há base tecnológica explicitada no PDI ou não é apresentada a descrição dos recursos tecnológicos disponíveis.","2":"A base tecnológica explicitada no PDI apresenta a descrição dos recursos tecnológicos disponíveis e considera a capacidade e a estabilidade da energia elétrica, a rede lógica e o acordo do nível de serviço.","3":"A base tecnológica explicitada no PDI apresenta a descrição dos recursos tecnológicos disponíveis e considera a capacidade e a estabilidade da energia elétrica, a rede lógica, o acordo do nível de serviço e a segurança da informação.","4":"A base tecnológica explicitada no PDI apresenta a descrição dos recursos tecnológicos disponíveis e considera a capacidade e a estabilidade da energia elétrica, a rede lógica, o acordo do nível de serviço, a segurança da informação e o plano de contingência.","5":"A base tecnológica explicitada no PDI apresenta a descrição dos recursos tecnológicos disponíveis e considera a capacidade e a estabilidade da energia elétrica, a rede lógica, o acordo do nível de serviço, a segurança da informação e o plano de contingência, com condições de funcionamento 24 horas por dia, 7 dias por semana."},"applicability":"Exclusivo para IES que preveem em seu PDI a adoção de metodologia baseada em recursos da Internet.","nota":null,"evidence":{"obrigatoria":["Descrição da base tecnológica explicitada no PDI","Inventário dos recursos tecnológicos disponíveis","Comprovação da capacidade e da estabilidade do fornecimento de energia elétrica","Documento de acordo de nível de serviço com o provedor","Política de segurança da informação e plano de contingência"],"complementar":["Relatório de disponibilidade da rede lógica","Registro de incidentes e de tempo de resposta","Topologia da rede e da infraestrutura de contingência"],"resultado":["Série de disponibilidade do serviço, com meta de funcionamento 24 horas por dia, 7 dias por semana","Incidente registrado e tratado conforme o plano de contingência, com tempo de recuperação","Melhoria de capacidade executada a partir de medição"]},"alerta":"O critério exige condições de funcionamento contínuo, 24 por 7. Acordo de nível de serviço inexistente ou sem medição de disponibilidade não comprova a condição e para o indicador no conceito 3."}'::jsonb),
  ('5.15','5','Infraestrutura de execução e suporte','Exclusivo para IES que preveem em seu PDI a adoção de metodologia baseada em recursos da Internet.','{"sinaes_dimension":7,"concept_descriptors":{"1":"A infraestrutura de execução e suporte não atende às necessidades institucionais.","2":"A infraestrutura de execução e suporte não atende às necessidades institucionais, considerando a disponibilidade de serviços.","3":"A infraestrutura de execução e suporte atende às necessidades institucionais, considerando a disponibilidade de serviços e meios apropriados para sua oferta.","4":"A infraestrutura de execução e suporte atende às necessidades institucionais, considerando a disponibilidade de serviços e meios apropriados para sua oferta, e apresentando um plano de contingência.","5":"A infraestrutura de execução e suporte atende às necessidades institucionais, considerando a disponibilidade de serviços e meios apropriados para sua oferta, apresentando um plano de contingência, redundância e expansão."},"applicability":"Exclusivo para IES que preveem em seu PDI a adoção de metodologia baseada em recursos da Internet.","nota":null,"evidence":{"obrigatoria":["Relação dos serviços ofertados e dos meios disponíveis para sua oferta","Plano de contingência documentado","Plano de redundância documentado","Plano de expansão da infraestrutura de execução e suporte"],"complementar":["Relatório de capacidade instalada e de utilização","Registro de testes de contingência realizados","Escala da equipe de suporte e de operação"],"resultado":["Série de disponibilidade dos serviços no triênio","Teste de contingência executado, com resultado e correção","Expansão executada contra o plano, com data"]},"alerta":"Plano de contingência que nunca foi testado não comprova a capacidade de suportar falha. Infraestrutura sem redundância declarada reprova o critério."}'::jsonb),
  ('5.16','5','Plano de expansão e atualização de equipamentos',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"Não há plano de expansão e atualização de equipamentos descrito no PDI.","2":"Não há viabilidade para executar o plano de expansão e atualização de equipamentos descrito no PDI.","3":"Há viabilidade para executar o plano de expansão e atualização de equipamentos descrito no PDI. instrumento de avaliação institucional externa | presencial e A distância Recredenciamento | Transformação de Organização Acadêmica 32 CONCEITO CRITÉRIO DE ANÁLISE","4":"Há viabilidade para executar o plano de expansão e atualização de equipamentos descrito no PDI, com acompanhamento baseado em metas objetivas e mensuráveis, por meio de indicadores de desempenho.","5":"Há viabilidade para executar o plano de expansão e atualização de equipamentos descrito no PDI, com acompanhamento baseado em metas objetivas e mensuráveis, por meio de indicadores de desempenho; adicionalmente, há ações associadas à correção do plano."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Plano de expansão e atualização de equipamentos descrito no PDI","Demonstração de viabilidade financeira de execução do plano","Indicadores de desempenho institucionalizados para acompanhar o plano","Registro de acompanhamento baseado em metas objetivas e mensuráveis"],"complementar":["Relatório de aquisições e de baixas de equipamentos no triênio","Inventário patrimonial atualizado","Registro de ações de correção do plano"],"resultado":["Série de execução do plano contra o previsto, no triênio","Ação corretiva do plano executada, com efeito medido","Indicador de idade média do parque de equipamentos"]},"alerta":"Plano previsto no PDI e sem viabilidade financeira demonstrada não atende ao critério. O critério é cumulativo: sem a ação de correção do plano, o indicador fica em conceito 4."}'::jsonb),
  ('5.17','5','Recursos de tecnologias de informação e comunicação',NULL,'{"sinaes_dimension":7,"concept_descriptors":{"1":"Os recursos de tecnologias de informação e comunicação não asseguram a execução do PDI.","2":"Os recursos de tecnologias de informação e comunicação asseguram a execução do PDI, mas não viabilizam as ações acadêmico-administrativas ou não garantem a acessibilidade comunicacional.","3":"Os recursos de tecnologias de informação e comunicação asseguram a execução do PDI, viabilizam as ações acadêmico-administrativas e garantem a acessibilidade comunicacional.","4":"Os recursos de tecnologias de informação e comunicação asseguram a execução do PDI, viabilizam as ações acadêmico-administrativas, garantem a acessibilidade comunicacional e permitem a interatividade entre os membros da comunidade acadêmica.","5":"Os recursos de tecnologias de informação e comunicação asseguram a execução do PDI, viabilizam as ações acadêmico-administrativas, garantem a acessibilidade comunicacional, permitem a interatividade entre os membros da comunidade acadêmica e apresentam soluções tecnológicas comprovadamente inovadoras."},"applicability":null,"nota":null,"evidence":{"obrigatoria":["Inventário dos recursos de tecnologias de informação e comunicação","Documento que demonstra a execução do PDI por meio dos recursos de TIC","Comprovação de acessibilidade comunicacional dos recursos","Registro de uso dos recursos para a interatividade da comunidade acadêmica"],"complementar":["Política de aquisição e de renovação de TIC","Relatório de suporte e de manutenção dos recursos","Registro de soluções tecnológicas inovadoras implantadas"],"resultado":["Série de adoção dos recursos pela comunidade no triênio","Solução inovadora implantada, com resultado documentado","Indicador de disponibilidade dos recursos, com meta e realizado"]},"alerta":"Recurso implantado e não adotado não comprova interatividade. Sem acessibilidade comunicacional comprovada, o indicador não passa do conceito 3."}'::jsonb),
  ('5.18','5','Ambiente Virtual de Aprendizagem - AVA','Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n°1.134 de 10/10/2016.','{"sinaes_dimension":7,"concept_descriptors":{"1":"O AVA não atende aos processos de ensino-aprendizagem, conforme disposto nas políticas institucionais para educação a distância estabelecidas pela IES.","2":"O AVA atende aos processos de ensino-aprendizagem, conforme disposto nas políticas institucionais para educação a distância estabelecidas pela IES.","3":"O AVA atende aos processos de ensino-aprendizagem, conforme disposto nas políticas institucionais para educação a distância estabelecidas pela IES, garantindo a interação entre docentes, discentes e tutores.","4":"O AVA está integrado com o sistema acadêmico e atende aos processos de ensino-aprendizagem, conforme disposto nas políticas institucionais para educação a distância estabelecidas pela IES, garantindo a interação entre docentes, discentes e tutores.","5":"O AVA está integrado com o sistema acadêmico e atende aos processos de ensino-aprendizagem, conforme disposto nas políticas institucionais para educação a distância estabelecidas pela IES, garantindo a interação entre docentes, discentes e tutores, com adoção de recursos inovadores."},"applicability":"Exclusivo para modalidade a distância e para IES que visa a ofertar ou oferta cursos com disciplinas (integral ou parcialmente) na modalidade a distância, conforme Portaria n°1.134 de 10/10/2016.","nota":null,"evidence":{"obrigatoria":["Documento de integração entre o AVA e o sistema acadêmico","Política institucional de educação a distância que rege o uso do AVA","Registro de interação entre docentes, discentes e tutores no AVA","Relatório de uso do AVA nos processos de ensino-aprendizagem"],"complementar":["Manual de uso do AVA para docentes e discentes","Relatório de disponibilidade e de suporte do AVA","Registro de recursos inovadores adotados no ambiente"],"resultado":["Série de acesso e de interação no AVA no triênio","Indicador de integração entre AVA e sistema acadêmico, com meta e realizado","Recurso inovador adotado, com resultado documentado"]},"alerta":"AVA que roda separado do sistema acadêmico não atende ao critério, ainda que funcione bem. Interação declarada sem registro de acesso não comprova o uso."}'::jsonb)
 ) AS v(code,dim,label,descr,ref)
